INSERT INTO `paper` VALUES ('732', '31', 'l03', 'Seznam vystavovatelů', '<p style=\"text-align: left;\"><span style=\"color: #000000;\"><strong><strong><strong><strong><span style=\"color: #000000;\"><strong>Kdo vystavoval v roce 2024?</strong></span></strong></strong></strong></strong><span style=\"color: #000000;\">&nbsp;</span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"color: #000000;\"><span style=\"color: #000000;\">(v abecedn&iacute;m pořad&iacute;):</span></span></p>\r\n<p><strong><a href=\"https://www.asteelflash.com/facility/asteelflash-plzen-s-r-o/\" target=\"_blank\" rel=\"noopener\">Asteelflash Plzeň s.&nbsp;r.&nbsp;o.</a></strong></p>\r\n<p><a href=\"https://bergerholding.eu/cs/%C4%8Desko/kari%C3%A9ra\" target=\"_blank\" rel=\"noopener\"><strong> BERGER BOHEMIA a.&nbsp;s.</strong></a></p>\r\n<p><a href=\"https://pracevchristu.cz/\" target=\"_blank\" rel=\"noopener\"><strong> CHRIST CAR WASH s.&nbsp;r.&nbsp;o.</strong></a></p>\r\n<p><a href=\"https://www.carrier.com/commercial-refrigeration/cs/cz/about/about-commercial-refrigeration-czech-rep-operations/\" target=\"_blank\" rel=\"noopener\"><strong> Carrier Refrigeration Operation Czech Republic s.&nbsp;r.&nbsp;o.</strong></a></p>\r\n<p><a href=\"https://tvojebudoucnost.jobs.cz/\" target=\"_blank\" rel=\"noopener\"><strong> Česk&aacute; po&scaron;ta, s.&nbsp;p.</strong></a></p>\r\n<p><a href=\"https://www.daikin.cz/cs_cz/toto-je-daikin.html\" target=\"_blank\" rel=\"noopener\"><strong> Daikin Industries Czech Republic s. r. o.</strong></a></p>\r\n<p><a href=\"http://www.dzklatovy.cz/cesky/firma/spolecnost/zamestnani/\" target=\"_blank\" rel=\"noopener\"><strong> Drůbež&aacute;řsk&yacute; z&aacute;vod Klatovy a.&nbsp;s.</strong></a></p>\r\n<p><a href=\"https://www.elkamet.com/cz/kariera\" target=\"_blank\" rel=\"noopener\"><strong> Elkamet s.&nbsp;r.&nbsp;o.</strong></a></p>\r\n<p><a href=\"https://www.faurecia-cz.cz/\" target=\"_blank\" rel=\"noopener\"><strong> FORVIA Faurecia Plzeň s.&