INSERT INTO `paper` VALUES ('741', '40', 'l06', 'ROK 2015', '<p style=\"text-align: left;\"><span style=\"font-size: small;\"><strong>Veletrh práce a vzdělávání Kllč k příležitostem proběhl 22.1.2015.</strong></span></p>\r\n<p><span style=\"font-size: small;\">Děkujeme za Vaši přízeň, budeme se na Vás těšit zase koncem ledna 2016.</span></p>\r\n<p><span style=\"font-size: small;\">Mezitím si můžete prohlédnout <a title=\"fotogalerie veletrh 2015\" href=\"../index.php?list=l06_01&language=lan1&lay=\" target=\"_blank\">fotogalerii</a> či <a title=\"tiskové zprávx pro média\" href=\"../index.php?list=l06_06&language=lan1&lay=\" target=\"_blank\">tiskové zprávy</a>.</span></p>\r\n<p><br /><span style=\"font-size: small;\"><strong>Veletrh je určen široké veřejnosti, těm, kteří chtějí najít či změnit práci, hledají stáž či brigádu, rekvalifikaci nebo jazykové kurzy. Je otevřen i všem studentům a absolventům vysokých a středních škol, odborných škol a učilišť.</strong></span><br /><br /><span style=\"font-size: small;\">Součástí veletrhu je každoročně bohatý <a title=\"doprovodný program veletrhu\" href=\"../index.php?list=l06_03&language=lan1&lay=\" target=\"_blank\">doprovodný program</a>.</span><br /><span style=\"font-size: small;\"><strong>Vstup je pro všechny návštěvníky zdarma.</strong></span></p>\r\n<p style=\"text-align: center;\"><strong><span style=\"font-size: small;\"></span></strong><span style=\"font-size: medium;\"><strong><strong><span style=\"font-size: medium;\"><br /></span></strong></strong></span></p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>', '', '', 'jab1408', '2019-10-10 12:26:11');
INSERT INTO `paper` VALUES ('742', '41', 'l06', 'ROK 2015', null, '', null, 'jab1408', '2019-10-10 12:26:11');
INSERT INTO `paper` VALUES ('743', '42', 'l06', 'ROK 2015', null, '', null, 'jab1408', '2019-10-10 12:26:11');
INSERT INTO `paper` VALUES ('744', '43', 'l06_01', 'Fotogalerie 2015', '<p><img style=\"width: 529px; height: 307px;\" src=\"files/1131782.jpg\" alt=\"soubor DSC_0146.jpg\" width=\"1022\" height=\"683\" /></p>\r\n<p>Veletrh navštívilo 2900 osob v průběhu jediného dne</p>\r\n<p><img style=\"width: 529px; height: 327px;\" src=\"files/1585009.jpg\" alt=\"soubor DSC_0191.jpg\" width=\"1015\" height=\"684\" /></p>\r\n<p>Společnost Steelcase hledala kvalifikované specialisty i dělníky do výroby</p>\r\n<p><img style=\"width: 529px; height: 328px;\" src=\"files/3364367.jpg\" alt=\"soubor DSC_0876.jpg\" width=\"1020\" height=\"742\" /></p>\r\n<p>Fond dalšího vzdělávání nabízel stáže ve firmách pro absolventy</p>\r\n<p><img style=\"width: 531px; height: 343px;\" src=\"files/9425901.jpg\" alt=\"Český rozhlas reportáž\" width=\"1023\" height=\"683\" /></p>\r\n<p>Veletrh vzbudil zájem médií</p>\r\n<p><img style=\"width: 531px; height: 333px;\" src=\"files/1136243.jpg\" alt=\"soubor DSC_0161.jpg\" width=\"1016\" height=\"681\" /></p>\r\n<p>Společnost Sony DADC lákala zájemce o práci i zajímavými dárky v soutěži</p>\r\n<p><img style=\"width: 531px; height: 373px;\" src=\"files/1582032.jpg\" alt=\"stánek Loma Systems\" width=\"1019\" height=\"680\" /></p>\r\n<p><img style=\"width: 531px; height: 293px;\" src=\"files/4917556.jpg\" alt=\"soubor DSC_0177.jpg\" width=\"1022\" height=\"707\" /></p>\r\n<p> Personální testování na počítači - výstupní protokol lze přiložit k životopisu</p>\r\n<p><img style=\"width: 531px; height: 291px;\" src=\"files/1812378.jpg\" alt=\"soubor DSC_0249.jpg\" width=\"1023\" height=\"683\" /></p>\r\n<p>Zástupkyně HR oddělení společnosti Steelcase</p>\r\n<p><img style=\"width: 531px; height: 352px;\" src=\"files/2882710.jpg\" alt=\"soubor DSC_0230.jpg\" width=\"1020\" height=\"680\" /></p>\r\n<p>Střední škola Kralovice upoutala simulátorem svařování</p>\r\n<p><img style=\"width: 531px; height: 352px;\" src=\"files/1121433.jpg\" alt=\"soubor DSC_0203.jpg\" width=\"1020\" height=\"675\" /></p>\r\n<p>Každou hodinu se losovaly anketní lístky o ceny věnované pořadatelem a rádiem FM+</p>\r\n<p><img style=\"width: 531px; height: 304px;\" src=\"files/1497606.jpg\" alt=\"soubor DSC_0257.jpg\" width=\"1019\" height=\"682\" /></p>\r\n<p>V přednáškových místnostech probíhaly semináře s tématem práce a vzdělávání</p>\r\n<p><img style=\"width: 533px; height: 357px;\" src=\"files/1932377.jpg\" alt=\"soubor DSC_0284.jpg\" width=\"1019\" height=\"713\" /></p>\r\n<p>Ocenění Mamma/Parent Friendly obdržely 4 společnosti, zde Rondo obaly</p>\r\n<p><img style=\"width: 533px; height: 298px;\" src=\"files/1883120.jpg\" alt=\"soubor DSC_0292.jpg\" width=\"1016\" height=\"803\" /></p>\r\n<p>Ocenění Mamma/Parent Friendly obdržely 4 společnosti, zde Triumfa</p>\r\n<p><img style=\"width: 535px; height: 332px;\" src=\"files/1818912.jpg\" alt=\"soubor DSC_0313.jpg\" width=\"1020\" height=\"703\" /></p>\r\n<p>Mamma/Parent Friendly - oceněné podniky: Triumfa, Rondo obaly, Drůbežářský závod Klatovy, Murr CZ</p>\r\n<p><img style=\"width: 533px; height: 388px;\" src=\"files/2003341.jpg\" alt=\"soubor DSC_0450.jpg\" width=\"1021\" height=\"682\" /></p>\r\n<p>Křest knihy PaedDr. Marie Maškové Grafologie nejen pro personalisty</p>\r\n<p><img style=\"width: 536px; height: 331px;\" src=\"files/1158165.jpg\" alt=\"soubor DSC_9910.jpg\" width=\"1022\" height=\"681\" /></p>\r\n<p>...a následná autogramiáda</p>\r\n<p><img style=\"width: 536px; height: 308px;\" src=\"files/1322730.jpg\" alt=\"soubor DSC_0909.jpg\" width=\"1022\" height=\"682\" /></p>\r\n<p>Rodenstock z Klatov hledal obchodníky i dělníky</p>\r\n<p><img style=\"width: 537px; height: 380px;\" src=\"files/1937926.jpg\" alt=\"soubor 20150122_113236.jpg\" width=\"1019\" height=\"764\" /></p>\r\n<p>Image poradnu návštěvníci využívají na veletrhu již třetím rokem </p>\r\n<p><img style=\"width: 537px; height: 332px;\" src=\"files/1620229.jpg\" alt=\"soubor DSC_0065.jpg\" width=\"1022\" height=\"683\" /></p>\r\n<p><img style=\"width: 537px; height: 352px;\" src=\"files/1012844.jpg\" alt=\"soubor DSC_0383.jpg\" width=\"1020\" height=\"681\" /></p>\r\n<p><img style=\"width: 535px; height: 362px;\" src=\"files/1833041.jpg\" alt=\"soubor DSC_0899.jpg\" width=\"1020\" height=\"681\" /></p>\r\n<p><img style=\"width: 537px; height: 346px;\" src=\"files/1045447.jpg\" alt=\"soubor DSC_9749.jpg\" width=\"1023\" height=\"679\" /></p>\r\n<p><img style=\"width: 537px; height: 314px;\" src=\"files/1360339.jpg\" alt=\"soubor DSC_0914.jpg\" width=\"1019\" height=\"682\" /></p>\r\n<p><img style=\"width: 537px; height: 362px;\" src=\"files/1356319.jpg\" alt=\"soubor DSC_0921.jpg\" width=\"1018\" height=\"681\" /></p>\r\n<p>Vedle podniků vystavovaly i vzdělávací instituce</p>\r\n<p><img style=\"width: 537px; height: 266px;\" src=\"files/7389909.jpg\" alt=\"soubor DSC_9696.jpg\" width=\"1023\" height=\"682\" /></p>\r\n<p> </p>\r\n<p><img style=\"width: 537px; height: 319px;\" src=\"files/2739403.jpg\" alt=\"soubor DSC_0231.jpg\" width=\"1023\" height=\"682\" /></p>\r\n<p><img style=\"width: 537px; height: 327px;\" src=\"files/1019163.jpg\" alt=\"soubor DSC_0882.jpg\" width=\"1019\" height=\"684\" /></p>\r\n<p>Personální ředitelka Steelcase Helena Sanchez přijela až z Mexika</p>\r\n<p><img style=\"width: 540px; height: 473px;\" src=\"files/1720794.jpg\" alt=\"soubor DSC_0868upr.jpg\" width=\"1023\" height=\"729\" /></p>', '', 'fotogalerie veletrh práce a vzdělávání', 'jab1408', '2015-09-23 12:56:13');
