INSERT INTO `paper` VALUES ('840', '139', 'l06_05', 'Mediální partneři', '<p> </p>\r\n<p><a href=\"http://www.plzen2015.cz\"><img src=\"files/8997277.jpg\" alt=\"soubor Plzen2015.jpg\" width=\"168\" height=\"63\" />  <span style=\"color: #000000; font-size: medium;\"> </span></a></p>\r\n<p><a href=\"http://www.regionplzen.cz\">           </a></p>\r\n<p> </p>\r\n<p><a href=\"http://www.rozhlas.cz/plzen/portal/\"><img src=\"files/1003123.png\" alt=\"soubor cesky_rozhlas.png\" width=\"170\" height=\"68\" /></a></p>\r\n<p> </p>\r\n<p><a href=\"http://www.plzen.cz\"><img src=\"files/6319088.jpg\" alt=\"soubor PLZEN_CZ_logo_zpravodajsky_portal_jpg-1.jpg\" width=\"178\" height=\"125\" /></a></p>\r\n<p><a href=\"http://www.reginplzen.cz\"><img src=\"files/1129569.png\" alt=\"soubor logo_regionprace_nove.png\" width=\"200\" height=\"25\" /></a></p>\r\n<p> </p>\r\n<p> </p>\r\n<p><a href=\"http://www.edumenu.cz\"><img src=\"files/1804258.png\" alt=\"soubor edumenu.png\" width=\"169\" height=\"47\" /></a></p>\r\n<p> </p>\r\n<p><a href=\"http://www.hitradiofmplus.cz/\"><img src=\"files/1615884.jpg\" alt=\"soubor FM Plus_zapadni Cechy.jpg\" width=\"172\" height=\"84\" /></a></p>\r\n<p> </p>\r\n<p><a href=\"http://www.prace.cz\"><img src=\"files/1780954.gif\" alt=\"soubor prace_noclaim.gif\" width=\"179\" height=\"34\" /> </a></p>\r\n<p> </p>\r\n<p> </p>\r\n<p>  <a href=\"http://www.personalista.com\"><img src=\"files/1738641.png\" alt=\"soubor logo-personalista.png\" width=\"177\" height=\"37\" /></a></p>\r\n<p> </p>\r\n<p><a href=\"http://umo3.plzen.eu/\"><img src=\"files/3644257.jpg\" alt=\"soubor Obvod3.jpg\" width=\"146\" height=\"79\" /></a></p>\r\n<p> <a href=\"http://www.plzensky-kraj.cz/\"><img src=\"files/7875961.png\" alt=\"soubor Kraj.png\" width=\"78\" height=\"92\" /></a></p>\r\n<p> </p>\r\n<p> </p>', '', '', 'anv1305', '2015-09-23 12:56:12');
