INSERT INTO `paper` VALUES ('849', '148', 'l08', 'Profily vystavovatelů', '<p style=\"text-align: left;\"><span style=\"color: #000000; font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\"><span style=\"color: #000000; font-size: medium;\"><strong>Vystavovatelé </strong>(v abecedním pořadí)<strong>:</strong></span></span></strong></strong></span></strong></span></strong></span></p>\r\n<p><strong><span style=\"font-size: small;\">Alfmeier CZ s.r.o.</span></strong></p>\r\n<p style=\"text-align: left;\"><strong><span style=\"font-size: medium;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Ball Beverage Packaging Czech republic s.r.o.</span></span></span></strong></p>\r\n<p style=\"text-align: left;\"><strong><span style=\"font-size: medium;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">BERGER BOHEMIA a.s.</span></span></span></strong></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong>CANPACK Czech s.r.o.</strong></span></strong></span></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\">Carrier Refrigeration Operation Czech Republic s.r.o.</span></strong></strong></span></strong></span></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\">ČEZ, a.s.</span></strong></strong></span></strong></span></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong>Daikin Industries Czech Republic s.r.o.</strong></span></strong></span></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>DFH Haus CZ s.r.o.</strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\">Drůbežářský závod Klatovy a.s.</span></strong></strong></span></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong>EvoBus Česká republika s.r.o.</strong></span></strong></span></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong>Fakulta zdravotnických studií ZČU v Plzni</strong></span></strong></span></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"color: #000000; font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong>Gymnázium a SOŠ Rokycany<br /></strong></span></strong></span></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\"><span style=\"font-size: small;\"><strong>CHRIST CAR WASH s.r.o.</strong></span></span></strong></strong></span></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\">JTEKT Czech Republic s.r.o.</span></strong></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\">Kermi s.r.o.</span></strong></span></strong></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"color: #000000; font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\">Krajské ředitelství policie Plzeňského kraje<br /></span></strong></span></strong></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\">La Lorraine, a.s.</span></strong></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\">Linde Pohony s.r.o. / KION Stříbro</span></strong></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\"><span style=\"font-size: small;\"><strong>MD Elektronik spol. s r.o.</strong></span></span></strong></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: small;\"><strong><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\">MURR CZ, s.r.o.</span></strong></span></strong></strong></span></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"color: #000000; font-size: medium;\"><strong><span style=\"font-size: small;\"><strong>