INSERT INTO `paper` VALUES ('858', '157', 'l09_02', 'FOTOGALERIE 2017', '<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/2896223.jpg\" alt=\"soubor 20170126_104143Pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\">Na veletrh přišly práci hledat i matky s malými dětmi</p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1509166.jpg\" alt=\"soubor bez názvu-5051_pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\"> Veletrh zahájili: Jana Brabcová, jednatelka pořádající společnosti Grafia, Eva Herinková, náměstkyně primátora města Plzně, Ivana Šatrová za krajskou pobočku úřadu práce v Plzni a Milan Edl, děkan Fakulty strojní Západočeské univerzity v Plzni</p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/2056918.jpg\" alt=\"soubor 20170126_104608_pro web.jpg\" />Jednotlivé podniky nabízely lepší mzdy a benefity - zde KS EUROPE</p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/2084920.jpg\" alt=\"soubor 20170126_104713_pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/7507048.jpg\" alt=\"soubor bez názvu-5320_orez_mala_pro web.jpg\" />V letošním roce cenu Mamma/Parent Friendly získaly společnosti<strong> Shape Corp. Czech Republic, s.r.o., ADP Employer Services Česká republika, a.s., LUBRICANT s.r.o. , DHL Solutions k.s. Nýřany</strong></p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/9989549.jpg\" alt=\"soubor bez názvu-5077_pro web.jpg\" />Na stánku Daikin jste mohli získat práci a ochutnat sushi</p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1513129.jpg\" alt=\"soubor 20170126_104208_pro web.jpg\" /></p>\r\n<p> </p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1332371.jpg\" alt=\"soubor bez názvu-5337_mala.jpg\" />Každou hodinu se losovaly 3 ceny pro ty, kdo vyplnili anketní lístky. Nakonec jsme měli cca 500 anketních lístků, což je celá šestina návštěvníků!</p>\r\n<p> <img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1033337.jpg\" alt=\"soubor bez názvu-5110_mala.jpg\" /></p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/3072052.jpg\" alt=\"soubor bez názvu-5269_pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\">Kosmetičky a kadeřnice upravovaly zejména ty, kteří se chtěli vyfotit do životopisu</p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/6588290.jpg\" alt=\"soubor bez názvu-5087_pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\">Ta paní nehledá práci pro sebe, ale pro celou třídu končících nástrojářů - je to jejich učitelka!</p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1075028.jpg\" alt=\"soubor bez názvu-5141_pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\">S úsměvem jde všechno líp!</p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/6655240.jpg\" alt=\"soubor bez názvu-5135_pro web.jpg\" /></p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1580132.jpg\" alt=\"soubor bez názvu-5288_pro web.jpg\" /></p>\r\n<p> </p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/8299497.jpg\" alt=\"soubor bez názvu-5290pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\">Ze zákulisí - i tam vládl úsměv a dobrá nálada - na fotce Štěpánka Pirnosová, obchodní ředitelka Grafia, a Jana Brabcová, jednatelka</p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1540647.jpg\" alt=\"soubor bez názvu-5282_pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\">Testování zrakové kondice</p>\r\n<p> </p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/2577868.jpg\" alt=\"soubor 20170126_115212_pro Web.jpg\" /></p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1110199.jpg\" alt=\"soubor 20170126_105326_pro web.jpg\" /></p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1674621.jpg\" alt=\"soubor 20170126_114103_pro web.jpg\" /></p>\r\n<p style=\"text-align: center;\">Czechinvest radil zdarma a mezi množstvím těch, kteří našli odvahu konzultovat svůj podnikatelský záměr, se našlo cca 10 opravdu smysluplných nápadů!</p>', '', '', 'administrator', '2017-09-20 13:46:02');
INSERT INTO `paper` VALUES ('859', '158', 'l09_02', 'FOTOGALERIE 2017', null, '', null, 'administrator', '2017-09-20 13:46:02');
INSERT INTO `paper` VALUES ('860', '159', 'l09_02', 'FOTOGALERIE 2017', null, '', null, 'administrator', '2017-09-20 13:46:02');
INSERT INTO `paper` VALUES ('861', '160', 'l09_03', 'Pro média', '<h2 style=\"text-align: left;\"><span style=\"font-size: small;\"><strong><em>Několik statistických údajů z letošního ročníku:</em></strong></span></h2>\r\n<p><strong><span style=\"font-size: small;\">1) Důvod návštěvy:</span></strong></p>\r\n<p><span style=\"font-size: small;\">Většina návštěvníků přišla hledat práci nebo lepší práci (52%), celých 22% vnímalo 5.ročník veletrhu jako příležitost, jako zdroj informací a cca 15% pak hledalo brigádu.<br /></span></p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1578489.png\" alt=\"soubor graf1.png\" width=\"553\" height=\"350\" /></p>\r\n<p><strong><em><br /></em></strong></p>\r\n<p><strong><em><strong><span style=\"font-size: small;\">2) Aktuální angažmá:</span></strong></em></strong></p>\r\n<p><span style=\"font-size: small;\">Veletrh navštívilo více než 35% nezaměstnaných, přes 30% pracujících a velmi příznivých necelých 12% studentů VŠ.</span></p>\r\n<p> </p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/4366471.png\" alt=\"soubor graf2.png\" width=\"548\" height=\"347\" /></p>\r\n<p><strong><em><strong><span style=\"font-size: small;\"><br /></span></strong></em></strong></p>\r\n<p><strong><em><strong><span style=\"font-size: small;\">3) Nejvyšší dosažené vzdělání:<br /></span></strong></em></strong></p>\r\n<p><span style=\"font-size: small;\">Co do vzdělání byla největší skupina středoškoláků - více než 40%, přes 24% vysokoškoláků a více než 20% vyučených.</span></p>\r\n<p> </p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/7005112.png\" alt=\"soubor graf3.png\" width=\"556\" height=\"352\" /></p>\r\n<p> </p>\r\n<hr />\r\n<p style=\"text-align: left;\"><span style=\"color: #888888; font-size: small;\"><strong>Tisková zpráva č. 5</strong></span></p>\r\n<p><span style=\"font-size: small; color: #eb1b4c;\"><strong>Na veletrhu práce vítězily vyšší mzdy, benefity na míru a dobrá firemní kultura</strong></span></p>\r\n<p><em><img src=\"files/1912448.jpg\" alt=\"soubor IMG_9651_mala.jpg\" width=\"688\" height=\"515\" /></em></p>\r\n<p><em>Foto: Společnost RONDO nasbírala několi desítek životopisů<br /></em></p>\r\n<p><strong><em>Letošní ročník veletrhu práce a vzdělávání Klíč k příležitostem v plzeňském Pekle se nesl v duchu hledání lepší práce, vyšších mezd a benefitů. Je to jediný veletrh práce v Plzni pro širokou veřejnost. Organizátoři ze společnosti Grafia odhadují návštěvnost opět kolem 3000 osob různých profesí i různých věkových kategorií. Nejmladšímu návštěvníkovi bylo pět měsíců.</em></strong><br /><strong> <em>Práci nabízely podniky i personální agentury. Více než v předchozích letech vystavovaly i firmy operující mimo Plzeň. Letošní veletrh předčil očekávání personalistů i návštěvníků, dle jejich slov se letos více než kdy jindy potkávala nabídka pracovních míst s poptávkou.</em></strong></p>\r\n<p>Veletrh zahájila za organizátory jednatelka Grafie Jana Brabcová, náměstkyně primátora Plzně Eva Herinková, za plzeňský úřad práce jeho mluvčí Ivana Šatrová a Milan Edl, děkan Fakulty strojní ZČU v Plzni.  Zájem vystavovatelů v letošním roce převýšil očekávání organizátorů. <strong>Čtyři desítky firem nabízely více než tisícovku pracovních pozic</strong> od specializovaných a technicky orientovaných až po práci bez kvalifikačního požadavku a brigády.</p>\r\n<p>\"Výborná organizace, návštěvníků je hodně,\" hodnotí <strong>Julia Kovaleva ze společnosti Solar Turbines EAME</strong>. Oceňuje, že přišly i školy. \"Máme už několik desítek životopisů, pár velmi zajímavých, i zájemce z technických středních škol. Hledáme montážní a testovací inženýry, nákupčí, kvalitáře, administrativu - to vše pro nový závod v Žebráku. Veletrh má své přednosti, přímý kontakt se zájemcem je nejlepší. Při rozhovoru na stánku nebo následně u nás ve firmě můžeme nabídnout i jinou pracovní pozici. Ze životopisu to často nepoznáte, co by pisatel mohl dělat. Účast se nám určitě vyplatí,\" dodává Kovaleva.</p>\r\n<p>\"Chceme představit naši firmu i v širším okolí, je zde možnost prezentace a se zájemci se kontaktujeme telefonicky nebo mailem po veletrhu,\" <strong>říká Marie Pošarová ze společnosti Drůbežářský závod Klatovy</strong> a dodává: \"Letos vnímáme zájem kvalitnějších uchazečů. A těší nás, že někteří návštěvníci přímo přijdou a chválí naše výrobky.\"</p>\r\n<p><strong>Markéta Urbanová z personální agentury Hofmann</strong> si cení výbornou organizaci veletrhu. \"Díky známosti veletrhu  každoročně přijdou uchazeči připravení i s životopisy a vědí, co očekávají. Po veletrhu ještě dojde řada životopisů mailem nebo uchazeči přijdou rovnou na pobočku. Řada uchazečů jde ale přímo k zaměstnavateli a ne k agentuře, naší výhodou je, že máme více pracovních pozic k výběru a nabízíme i ubytování. Každý uchazeč dostává zpětnou vazbu k účasti ve výběrovém řízení.\"</p>\r\n<p>I společnost<strong> KS Europe </strong>považuje účast na veletrhu za smysluplnou. \"Přicházejí sem uchazeči, kteří se potkávají s poptávkou našich pracovních pozic, hledáme zejména dělnické pozice, ale i mistry, personalisty a předáky,\" říká <strong>Petra Auingerová, personalistka</strong>.</p>\r\n<p>\"Výhodou je, že sem přijdou lidé bez práce nebo ti, kteří mají zájem o změnu zaměstnání, a to i kvalifikovaní,\" říká <strong>Slavěna Langová, specialista vzdělávání a rozvoje MD Elektronik</strong> z Chotěšova. \"Naší výhodou je, že máme bezprašné a čisté prostředí, sedavé zaměstnání a k tomu svoz zaměstnanců z několika směrů vlastními autobusy.\"</p>\r\n<p>Každý si na veletrhu přišel na své. Celý den běžely <strong>odborné přednášky a poradny.</strong> Návštěvníkům radil právník, v poradně pro začínající podnikatele Czechinvest, kariérový poradce, optici testovali zrakovou kondici, profesionální fotograf pořídí fotku do životopisu, zdarma jsou i služby kadeřnic a kosmetiček.</p>\r\n<p>Ceny do slosování anket věnovali vystavovatelé i partneři veletrhu - flash disky, motorové mazivo, batohy i výpočetní techniku. Návštěvník Konstanty Figura se radoval z vyhrané ceny: \"Sotva jsem dorazil, ještě jsem se nestihl rozhlédnout a už jsem vyhrál cenu! Teď se jdu podívat na stánky firem.\"</p>\r\n<p><strong>Návštěvníci</strong> si pochvalovali <strong>rozmanitost pracovních nabídek</strong>. Mezi ně patří i Karolína Sedláková, která byla letos na veletrhu poprvé: \"Zatím studuji humanitní vědy, mluvím anglicky a německy a přišla jsem zjistit, kde bych mohla po složení státnic pracovat.\"</p>\r\n<p>Ľubomír Heglas, jeden z výherců cen, byl spokojený s nabídkou práce: \" Mám několik nabídek a tipů na práci a to je bezva.\" Na pódiu při přebírání ceny pak dodal: \"Ještě jsem nikdy v životě nic nevyhrál. To jste mi tedy udělali radost.\"</p>\r\n<p><strong>Mezi vystavovateli byly i školy</strong>, například VOŠ zdravotnická, managementu a veřejnosprávních studií. Veletrh je pro ně velmi zajímavý. \"Účast je určitě vyšší než loni a cílová skupina návštěvníků je přesně ta, kterou hledáme,\" říká Jiří Dvořák, vedoucí oboru cestovního ruchu. Mezi dalšími byla i Včelařská škola z Kolové a Západočeská univerzita.</p>\r\n<p>Na veletrhu byla také předána <strong>ocenění firmám přátelským rodině - Mamma/Parent Friendly</strong>. Toto ocenění zajímá nejen rodiče malých dětí, ale také mladé lidi, kteří hledají svobodu v zaměstnání a dobrou firemní kulturu. V letošním roce ji získaly společnosti<strong> Shape Corp. Czech Republic, s.r.o., ADP Employer Services Česká republika, a.s., LUBRICANT s.r.o. , DHL Solutions k.s. Nýřany. </strong></p>\r\n<p>Poradny byly plné po celý den až do večera, fotograf vyfotil kolem devadesáti osob, personální poradci zhodnotili přes stovku životopisů, pracovního právníka téměř udolala fronta klientů, optici poradili cca 60 lidem... Opět se mimořádně vydařila <strong>sbírka starých brýlí pro Lions Club</strong>, vybralo se jich kolem 400 ks a k tomu ještě společnost Daikin vybrala mezi zaměstnanci dalších 40 ks. Přednášky byly většinou obsazeny do posledního místa a zájem návštěvníků neopadal ani těsně před šestou, kdy se objevili ti, kteří pracují do pěti...<br /> Děkujeme všem příznivcům a těšíme se v lednu 2018!</p>\r\n<hr />\r\n<p><span style=\"color: #888888; font-size: small;\"><strong>Tisková zpráva č. 4. </strong></span><br /><span style=\"color: #888888; font-size: small;\"><strong></strong></span></p>\r\n<p><span style=\"color: #888888; font-size: small;\"><strong><span style=\"color: #eb1b4c;\">I nepotřebné brýle mohou pomoci. Přineste je ve čtvrtek na veletrh!</span></strong></span></p>\r\n<p class=\"western\" style=\"margin-bottom: 0.28cm; line-height: 107%;\"><em><span style=\"font-size: medium;\"></span>Brýle významným způsobem ovlivňují, jak vás ostatní vnímají. Vaše zraková kondice ovšem ovlivňuje váš pohled na svět i pracovní výkon. Téma zraku se prolíná i letošním veletrhem práce a vzdělávání, který proběhne už ve čtvrtek 26. 1. 2017 v plzeňském kulturním domě Peklo. Návštěvníci si mohou <strong>zdarma nechat otestovat zrakovou kondici, poradit se v image brýlové poradně, jaké obroučky nejlépe sedí a vyjadřují osobnost nositele. To vše je na veletrhu zdarma. Návštěvníci mohou ale „zaplatit“</strong> nepotřebnými brýlemi a přispět <strong>do sbírky pro země třetího světa. Pomoci mohou brýle dioptrické i sluneční, pro dospělé i děti.</strong></em></p>\r\n<p><span style=\"color: #000000;\"><strong>Brýle jsou nejčastější kompenzační pomůckou, která velmi úzce souvisí i s pracovním životem.</strong> Organizátor Grafia, s.r.o. realizuje tuto aktivitu ve spolupráci s Lions clubem v České republice. Lionské hnutí v ČR a SR již řadu let organizuje sběr použitých brýlí, které již jejich nositelé nepotřebují. Po celé republice jsou umístěny sběrné boxy a jeden takový najdou návštěvníci i na zmíněném veletrhu v Plzni. <strong>V loňském roce se na veletrhu vybralo přes 400 ks brýlí, což byl podle místního Lions clubu rekord. Bude letos překonán?</strong><br /></span></p>\r\n<p><span style=\"color: #000000;\">Ze všech sběrných míst pak brýle putují do centrálního skladu ve Zbuzanech u Prahy, odtud pak do lionského recyklačního centra Centro Italiano Lions Per La Raccota Degli Occhiali Usati (na celém světě je těchto recyklačních center 18). Zde se pak sesbírané<strong> použité dioptrické i sluneční brýle</strong> čistí, opravují, balí a zapisují do celosvětového registru. Žádné brýle se neztratí. I ty, které jsou v horším stavu, mohou posloužit například na náhradní díly.<br /></span></p>\r\n<p><span style=\"color: #000000;\">Odtud pak putují humanitárními cestami (např. za pomoci americké armády) za těmi, kdo je potřebují a nemají na ně - do cílových destinací v Africe, Asii i Jižní Americe. <br /></span></p>\r\n<p><span style=\"color: #000000;\">V předchozích letech bylo z České a Slovenské republiky do recyklačního centra v Itálii dovezeno přes 6000 kusů brýlí ročně. <br /><strong></strong></span></p>\r\n<p><span style=\"color: #000000;\"><strong>Dejte vašim nepoužívaným brýlím šanci pomáhat - mohou někomu na druhém konci zeměkoule pomoci konečně dobře vidět!</strong><br /><strong>Nezapomeňte své staré brýle přinést na Veletrh práce a vzdělávání 26. 1. 2017 mezi 10. a 18. hod! Sbírku najdete na balkonu hned vedle testování zrakové kondice.</strong></span></p>\r\n<p class=\"western\">------------</p>\r\n<p class=\"western\"><strong>Veletrh práce a vzdělávání, to fakt není nuda! <br /> </strong>Přednášky, poradny i fotky zdarma a navíc můžete vyhrát: volné vstupenky do Techmanie, velkou krabici müsli (půl kila - čoko, jahoda), flash disky, kravatu, knihy, motorový olej a mazivo na řetězy, diáře, bloky, zápisníky, kvalitní bílé víno a spoustu dalších dárků od štědrých partnerů (děkujeme!)<br /> Slosování anketních lístků každou hodinu.</p>\r\n<p class=\"western\"> </p>\r\n<hr />\r\n<p style=\"text-align: left;\"><span style=\"color: #888888; font-size: small;\"><strong>Tisková zpráva č. 3. <br /><br /><span style=\"color: #eb1b4c;\">Dotkne se vás průmyslová revoluce 4.0? Veletrh práce dá odpověď!</span></strong></span></p>\r\n<p class=\"western\"><em>Zatímco ve světě personalistiky se nadšeně mluví o průmyslové revoluci 4.0 a co přinese za úspory pro pracovní trh, obyčejný člověk přemýšlí, co se stane s jeho pracovní pozicí, až technologie postoupí tak daleko, že zaměstnávat lidi bude příliš drahé. Odborníci mluví o tom, že některé pozice budou zrušeny a nahrazeny výkonnými a přesnými počítači. Počítač totiž nejí, nespí a pracuje stále, tedy pokud nevypnou proud. Opravdu nás stroje nahradí?</em></p>\r\n<p class=\"western\">Trend v náboru zaměstnanců v Plzeňském kraji ukáže Veletrh práce a vzdělávání Klíč k příležitostem, který se koná 26. 1. 2017. V dnešní době, kdy nezaměstnanost v kraji se pohybuje kolem 3,5 %, se zdá, že pro zaměstnance nemůže být příznivější doba pro vyjednání lepších mezd či pracovních podmínek. Je tomu ale opravdu tak?</p>\r\n<p class=\"western\">Může se totiž stát, že zaměstnavatelé propočtou náklady na pracovní síly a zjistí, že je v některých profesích výhodnější nakoupit drahé, ale výkonné stroje a technologie, které lidi nahradí. „Mluví se o tom, že zaniknou některé jednoduché administrativní pozice, ale také pracovní místa v opakované výrobě, například na montážních linkách,“ říká Jana Brabcová, jednatelka pořádací společnosti Grafia. „Překvapením může být, že i některé právní úkony může vykonávat stroj, třeba rutinní rozesílání písemností v přestupkovém řízení. Přijít na veletrh znamená zjistit, která pracovní místa podniky obsazují a počítají s nimi do budoucna.“</p>\r\n<p class=\"western\">Na návštěvníky čekají čtyři desítky zaměstnavatelů a stovky různorodých nabídek práce, od specializovaných inženýrských pozic po jednoduché práce ve výrobě či brigády.</p>\r\n<p class=\"western\">Většina návštěvníků v předchozích letech ocenila možnost osobně se setkat s personalisty podniků, dát jim do ruky svůj životopis a domluvit se na případné následné schůzce. „Někteří návštěvníci v poslední době ani práci nehledali, jen si přišli „obhlédnout“ nabídky a porovnat, zda by byl o ně zájem,“ říká Štěpánka Pirnosová, manažerka veletrhu. „Ale byli i tací, kteří celý den strávili na přednáškách a v poradnách a byli nadmíru spokojeni. Jinde se totiž za poskytované služby platí nemalé peníze,“ dodává Š. Pirnosová.</p>\r\n<p class=\"western\">Letošní ročník má program opravdu nabitý – právník, grafolog, optik, kariérní poradce, fotograf, kadeřnice, kosmetičky, image poradce – to vše najdete na veletrhu zdarma po celý den.</p>\r\n<p class=\"western\">Veletrh také poradí začínajícím podnikatelům, jak nastartovat vlastní byznys.</p>\r\n<p class=\"western\">Každý si najde to své i na přednáškách – jak se připravit na pracovní pohovor, na co si dát pozor při uzavírání pracovních smluv, jak a získat až 50.000 Kč na své vzdělávání, jak prezentovat jako Steve Jobs či jak se „prodat“ co nejlépe. Novinkou letošního ročníku je přednáška o travel hackingu - jak cestovat s minimálními náklady za prací i na dovolenou.</p>\r\n<p class=\"western\">Přijít se zkrátka vyplatí, i když práci právě nehledáte.</p>\r\n<p class=\"western\">Veškeré info a přesné časy doprovodného programu na webu: <span style=\"text-decoration: underline;\"><strong><span style=\"color: #000080; text-decoration: underline;\"><a href=\"../\">http://praci.najdisi.cz</a></span></strong></span></p>\r\n<p class=\"western\">Na Facebooku najdete videopozvánky personalistů: <strong>www.facebook.com/veletrhprace/</strong></p>\r\n<hr />\r\n<p style=\"text-align: left;\"><span style=\"color: #888888; font-size: small;\"><strong>Tisková zpráva č. 2</strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"color: #eb1b4c;\"><span style=\"font-size: small;\">N</span><strong style=\"font-size: small;\"><span style=\"font-size: small;\">a veletrhu práce poradí zdarma právník, optik, kariérní poradce i grafolog</span></strong></span></p>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small; color: #000000;\"><em>Tradiční <strong>Veletrh práce a vzdělávání v plzeňském Pekle </strong>každoročně navštíví tři tisícovky lidí hledajících práci či brigádu. Pro řadu lidí bude letošní ročník <strong>ve znamení hledání lepší práce</strong> – lépe placené, s delší dovolenou či s dalšími benefity. Záštitu nad 5. ročníkem, který se koná <strong>26. ledna 2017,</strong>  převzali náměstkyně primátora Bc. Eva Herinková a senátor Lumír Aschenbrenner.</em></span></h2>\r\n<h2 style=\"text-align: left;\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small; color: #eb1b4c;\">Veletrh stále více navštěvují i lidé, kteří práci právě nehledají, ale potřebují <strong>inspiraci pro svůj rozvoj</strong>. Být ve svém oboru stále in je totiž podmínkou úspěchu. Ať už se jedná o znalost nových technologií, poslední verze kancelářského softwaru, jazyky či tzv. měkké dovednosti.  </span></h2>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Proto podobně jako v předchozích letech, i letos připravili pořadatelé ze společnosti Grafia pestrý <strong>doprovodný program s řadou novinek, který zahrnuje poradny a přednášky mezi 10:00 a 18:00</strong>.</span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Tradičně mají návštěvníci možnost nechat si <strong>zkontrolovat životopis</strong> odborníkem – kariérním poradcem a konzultovat své postupy při hledání práce. \"Pokud jde o vaše první zaměstnání nebo jste delší dobu zaměstnavatele neměnili, je nejistota pochopitelná,\" říká za organizátory Jana Brabcová, jednatelka společnosti. Úspěch u přijímacího pohovoru navíc závisí nejen na prokázání dovedností, ale i na příjemném chování a úpravě zevnějšku - s tím pomůže <strong>image a brýlová poradna</strong>.</span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Už loni se osvědčila <strong>bezplatná fotoslužba</strong>. Mnohým totiž chybí k životopisu či prezentaci na sociálních sítích vhodná profilová fotografie – tu si nyní mohou návštěvníci „odnést“ (respektive nechat zaslat na email) z veletrhu od <strong>profesionálního fotografa</strong>. Před samotným pózováním před fotoaparátem mají zájemci možnost se nechat správně a decentně <strong>učesat a nalíčit</strong>.</span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Velmi poptávaná je i <strong>bezplatná pracovně-právní poradna, </strong>kde se návštěvníci mohou dotazovat na správnost pracovních smluv, podmínek výpovědi i další problematiku v souvislosti se zaměstnáním.</span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Že k práci patří i dobrý zrak, potvrdí nejen ti, kteří tráví pracovní dobu před monitorem. I letos lze <strong>otestovat svoji zrakovou kondici refraktometrem</strong> a možná tak i předejít zhoršování počínajících očních vad.</span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Nejen fyzické, ale i duševní zdraví bude tématem na pracovním veletrhu – titul <strong>přednášky „Jak se pozná, že už jsem se zbláznil“</strong> humornou formou přiblíží vážné téma, se kterým pomáhá spolek Ledovec.</span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Ekonomické oživení dodává kuráž mnohým z nás rozjet svůj podnikatelský záměr. Jak na to se zájemci dozví díky <strong>přednášce a poradně pro začínající podnikatele</strong> v režii Czechinvestu. Novým tématem mezi přednáškami <strong>je travel hacking - </strong>umění <strong>levně cestovat nejen za prací.</strong></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Kromě zmíněných novinek se návštěvníci mohou těšit na již osvědčené položky v doprovodném programu Veletrhu práce a vzdělávání: <strong>grafologické poradenství, informace o rekvalifikacích, testování jazykové úrovně </strong>a zejména <strong>přednášky </strong>jsou lákadlem pro kohokoliv, kdo se rozhodl na sobě pracovat.</span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Každoročně aktivit přibývá. \"Těší mne, že už teď slyším od známých, že si vezmou půlden volna, aby si ověřili svou cenu na trhu a prošli poradny i přednášky. Myslím, že <strong>přijít se prostě vyplatí, i když práci právě nehledáte</strong>,“ dodává Brabcová. </span><br /><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"> <strong>Vstup na veletrh i na celý doprovodný program je</strong> <strong>zdarma</strong>. \"Zaplatit\" ale můžete starými brýlemi, které přinesete do sbírky pro potřebné. Loni se jich pro plzeňský Lions Club vybralo přes 400 kusů.</span></p>\r\n<h2 style=\"text-align: left;\"> </h2>\r\n<hr />\r\n<p style=\"text-align: left;\"><span style=\"color: #c0c0c0;\"><strong><span style=\"font-size: small;\">Tisková zpráva č.1:</span></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #eb1b4c; font-size: small;\"><strong>Dejte do diáře už dnes: 26. leden 2017! </strong></span><br /><span style=\"font-size: small;\"><strong><span style=\"color: #eb1b4c;\">Najděte lepší práci na veletrhu práce a vzdělávání</span></strong></span><br /><span style=\"font-size: small;\"><strong><span style=\"color: #eb1b4c;\">KLÍČ K PŘÍLEŽITOSTEM®</span></strong></span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Již <strong>pátý ročník</strong> úspěšného veletrhu práce a vzdělávání pod názvem Klíč k příležitostem připravuje plzeňská společnost Grafia, s.r.o. Veletrh proběhne <strong>26. ledna 2017 již tradičně v kulturním domě Peklo v Plzni.</strong> Letošní ročník se koná opět za spolupráce významných partnerů (Úřad práce, krajská pobočka v Plzni, Hospodářská komora, ZČU, AIVD ČR).</span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">„Pátý ročník bude specifický tím, že v Plzeňském kraji máme zatím nejnižší nezaměstnanost za posledních několik let (3,4%) a v míře zaměstnanosti soutěžíme s Prahou,\" sdělila za organizátory Štěpánka Pirnosová, obchodní ředitelka společnosti Grafia. <strong>Pracovní nabídky převažují nad množstvím lidí bez práce. V takové situaci bývají zaměstnavatelé ochotni připlatit na mzdách.</strong> „Je to jedinečná příležitost přijít pohovořit osobně s personalisty a zjistit cenu své práce na trhu či poohlédnout se po zaměstnavatelích, kteří nabízejí lepší pracovní podmínky,\" dodává Š. Pirnosová.</span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>Mezi vystavovateli jsou významní zaměstnavatelé v regionu</strong>, jako například Sony DADC Czech Republic, Ball Beverage Packaging Czech Republic, Rondo obaly, PeHToo, Carrier Refrigeration Operation Czech Republic, Lear Corporation Czech Republic, Shape Corp. Czech Republic, HOFFMANN WIZZARD, Profesia CZ, Mubea Transmission Components, LUBRICANT, ČEZ, VIZA AUTO CZ, Drůbežářský závod Klatovy, RSF Elektronik, KS-Europe, Typos, tiskařské závody, Daikin Industries Czech Republic, Kermi, MD Elektronik, O2 Czech Republic, ZAT, MURR CZ, ZČU, Solar Turbines  EAME, DIOSS NÝŘANY a další. <strong>Nabízeno bude několik set pracovních pozic.</strong></span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>Aktuálně firmy hledají všechny úrovně kvalifikací a opravdu rozmanité profese pro muže i pro ženy:</strong> strojmistry, pomocníky ve výrobě, montážní techniky, inženýry kvality, testovací techniky, General Accountants, CNC operátory, lakýrníky, účetní, konstruktéry, vývojové inženýry, elektro – údržbáře, páječe, parťáky, obsluhy lisu, kvalitáře, operátory zpracování zboží, manipulanty, skladníky, obsluhy stroje, vedoucí stroje, techniky elektro, projektanty HW nebo SW, vývojáře, manažery projektů a obchodu, programátory – elektroniky, techniky oddělení Industry Engineering, techniky kvality, operátory a techniky v elektrovýrobě, montážní dělníky, vedoucí vstupní kontroly, techniky obrábění pro CNC, skladníky, mzdové účetní, personalisty, obsluhy CNC, obsluhy strojů na výrobu plechovek, obsluhy tiskového stroje, pracovníky elektra se znalostí PLC, technology, svářeče, letovače, elektrikáře, manipulanty ve výrobě, SMT techniky, projektové a procesní inženýry … <strong>Spektrum nabízených pracovních pozic je letos opravdu velmi široké.</strong></span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Veletrh je určen <strong>všem, kdo hledají práci či brigádu</strong> - lidem bez rozdílu věku či vzdělání, těm, <strong>kteří chtějí změnu</strong> či jsou aktuálně nespokojeni se svým místem, studentům posledních ročníků středních škol a jejich učitelům, vysokoškolákům i lidem registrovaným na úřadu práce. Všichni návštěvníci mají <strong>vstup v plném rozsahu zdarma.</strong></span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Velký zájem bývá tradičně i o <strong>doprovodný program.</strong> Témata přednášek souvisí s hledáním práce, např. jak se připravit na pracovní pohovor, jak se naučit „prodávat\" sám sebe či jak získat příspěvek na své vzdělávání a zlepšit tak svoji kvalifikaci, apod.</span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Na veletrhu budou opět vyhlášeny ceny <strong>Mamma/Parent Friendly</strong> <strong>pro podniky přátelské rodině,</strong> které vyhoví podmínkám hodnocení a vytvářejí dobré podmínky pro zaměstnance s rodinami, např. zkrácené úvazky, pružnou pracovní dobu, firemní školky či jesle, akce pro rodiny s dětmi či umožňují péči o rodinné příslušníky.</span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Po celý den bude probíhat zdarma <strong>poradenství v oblasti vzdělávání a trhu práce, image poradna, grafologické poradenství pro osobní rozvoj a řada dalších aktivit.</strong></span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong> „Nudit se určitě nebudete, přijďte, těšíme se na Vás,\"</strong> uzavírá Š. Pirnosová pozvánku na jubilejní 5. ročník veletrhu.</span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"> </span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>Kontakt: </strong>Ing. Štěpánka Pirnosová, obchodní ředitelka Grafia, s.r.o.</span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>Telefon:</strong> 377 227 701</span></p>\r\n<p class=\"western\" style=\"margin-left: 0.34cm; margin-right: 0.34cm; margin-bottom: 0.21cm; background: #ffffff; line-height: 100%;\" align=\"justify\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>E-mail:</strong> pirnosova@grafia.cz</span></p>', '', '', 'administrator', '2017-09-20 13:50:16');
