INSERT INTO `paper` VALUES ('987', '286', 'l09_06', 'Nabízená pracovní místa', '<h2 style=\"text-align: left;\"><strong>5. ročník veletrhu nabídne opravdu široké spektrum pracovních pozic pro všechny úrovně kvalifikací, pro muže, pro ženy:</strong></h2>\r\n<p><strong>Aktuálně firmy hledají:</strong></p>\r\n<table style=\"width: 666px; height: 402px;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"text-align: left; width: 6cm;\">\r\n<p><span style=\"font-size: x-small;\">Strojmistry/ně</span><br /><span style=\"font-size: x-small;\">Pomocníky/ice ve výrobě</span><br /><span style=\"font-size: x-small;\">Montážní techniky</span><br /><span style=\"font-size: x-small;\">Testovací techniky</span><br /><span style=\"font-size: x-small;\">Inženýry kvality</span><br /><span style=\"font-size: x-small;\">General Accountant</span><br /><span style=\"font-size: x-small;\">Quality Supervisor</span><br /><span style=\"font-size: x-small;\">Material Planner</span><br /><span style=\"font-size: x-small;\">Tool Designer</span><br /><span style=\"font-size: x-small;\">CNC operator</span><br /><span style=\"font-size: x-small;\">Manufacturing Engineer</span><br /><span style=\"font-size: x-small;\">Lakýrníky</span><br /><span style=\"font-size: x-small;\">Travel Accountant</span><br /><span style=\"font-size: x-small;\">Účetní</span><br /><span style=\"font-size: x-small;\">Konstruktéry</span><br /><span style=\"font-size: x-small;\">Vývojové inženýry</span><br /><span style=\"font-size: x-small;\">Elektro – údržbáře</span><br /><span style=\"font-size: x-small;\">Páječe</span><br /><span style=\"font-size: x-small;\">Parťáky (Zástupce vedoucího směnu)</span><br /><span style=\"font-size: x-small;\">Obsluhy lisu</span><br /><span style=\"font-size: x-small;\">Kvalitáře</span></p>\r\n<p><span style=\"font-size: x-small;\">Mechatroniky/Elektromechaniky</span><br /><span style=\"font-size: x-small;\">Seřizovače vstřikovacích lisů</span><br /><span style=\"font-size: x-small;\">Dělníky plastikářské výroby</span><br /><span style=\"font-size: x-small;\">Asistenty mistra vstřikovny</span></p>\r\n<p><span style=\"font-size: x-small;\">SAP Basis administrátory</span><br /><span style=\"font-size: x-small;\">Strojní programátory</span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Pracovníky dokončující zpracování</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Pomocníky k tiskovému stroji</span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Operátory skladu – obsluha VZV</span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Dělník/-ice v elektrotechnice<br />Seřizovače/mechaniky (M/Ž)<br />Obsluhy CNC frézky<br />Pracovníky interní logistiky (skladníky s VZV)</span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Brigádníky v tiskárně<br />Kameníky<br />Kontrolory kvality<br />Montážníky kabelových svazků<br />Montážní dělníky, CNC, lakýrníky<br />Pracovníky nakládky/vykládky poštovních balíků<br />Obsluhy válcovacích zařízení</span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Operátory/ky výroby</span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Obchodní zástupce<br /></span></span></span></span></p>\r\n</td>\r\n<td style=\"width: 6cm;\">\r\n<p><span style=\"font-size: x-small;\">Operátory zpracování zboží</span><br /><span style=\"font-size: x-small;\">Manipulanty</span><br /><span style=\"font-size: x-small;\">Skladníky (2 směnný provoz)</span><br /><span style=\"font-size: x-small;\">Obsluhy stroje</span><br /><span style=\"font-size: x-small;\">Vedoucí stroje</span><br /><span style=\"font-size: x-small;\">Skladníky (3 směnný provoz)</span><br /><span style=\"font-size: x-small;\">Techniky elektro</span><br /><span style=\"font-size: x-small;\">Projektanty HW nebo SW</span><br /><span style=\"font-size: x-small;\">Vývojáře</span><br /><span style=\"font-size: x-small;\">Manažery projektů a obchodu</span><br /><span style=\"font-size: x-small;\">Programátory – elektroniky</span><br /><span style=\"font-size: x-small;\">Techniky oddělení Industry Engineering</span><br /><span style=\"font-size: x-small;\">Techniky kvality</span><br /><span style=\"font-size: x-small;\">Operátory v elektrovýrobě</span><br /><span style=\"font-size: x-small;\">Techniky v elektrovýrobě</span><br /><span style=\"font-size: x-small;\">Lakýrníky</span><br /><span style=\"font-size: x-small;\">Montážní dělníky</span><br /><span style=\"font-size: x-small;\">Vedoucí vstupní kontroly</span><br /><span style=\"font-size: x-small;\">Techniky obrábění pro CNC soustruhy</span><br /><span style=\"font-size: x-small;\">Dělnice v elektrotechnice</span><br /><span style=\"font-size: x-small;\">Skladníky(ce) - vyskladňovací sklad</span><br /><span style=\"font-size: x-small;\">Skladníky(ce) - hlavní sklad</span><br /><span style=\"font-size: x-small;\">Mzdové účetní, personalistky</span></p>\r\n<p><span style=\"font-size: x-small;\">Operátory skladu</span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Frézaře CNC s praxí</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Strojírenské dělníky</span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: 