INSERT INTO `paper` VALUES ('993', '292', 'l10', 'ROK 2018', '<div style=\"float: right;\"><span style=\"font-size: medium;\"> <strong><span style=\"font-size: small;\"> <strong> <a title=\"Veletrh práce a vzdělávání Plzeň - Klíč k příležitostem\" href=\"https://www.facebook.com/veletrhprace\" target=\"_blank\"> <img style=\"margin: 10px 70px 10px 40px; float: right;\" title=\"facebook\" src=\"files/1153903.png\" alt=\"facebook\" width=\"58\" height=\"58\" /> </a><a title=\"Veletrh práce a vzdělávání Plzeň - Klíč k příležitostem\" href=\"https://www.facebook.com/veletrhprace\" target=\"_blank\"><br /> </a> </strong></span></strong> </span></div>\r\n<div><br />\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: medium;\"><span style=\"font-size: small; color: #eb1b4c;\">Jaký byl 6. ročník Veletrhu práce a vzdělávání? Pusťte si reportáž!</span></span></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: medium;\"><span style=\"font-size: small; color: #eb1b4c;\"></span><br /></span></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: medium;\"><span style=\"font-size: small;\"><span style=\"font-size: xx-small;\">--%VLOZVIDEOFLV_reportaz20180131%--</span></span></span></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium;\"><strong><span style=\"font-size: medium;\"><span style=\"font-size: x-small;\">---------</span><br /></span><span style=\"font-size: small;\"></span></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><strong>FOTOGALERIE ZDE: <a title=\"fotogalerie veletrhu 2018\" href=\"http://veletrhprace.rajce.idnes.cz/2018/\" target=\"_blank\">veletrhprace.rajce.net</a></strong></span></p>\r\n<p style=\"text-align: center;\"> <span style=\"font-size: small;\"><strong>Jak dopadla sbírka starých brýlí pro potřebné? Koukněte <a title=\"sbírka brýlí\" href=\"../index.php?list=l10_01&language=lan1&lay=\" target=\"_blank\">ZDE</a></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><strong>Kdo získal ocenění Mamma/Parent Friendly? Najdete <a title=\"Mamma/Parent Friendly 2018\" href=\"../index.php?list=l02&language=lan1&lay=\" target=\"_blank\">ZDE</a><br /></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><strong>Zprávy na PLZEN.cz: <a title=\"Zprávy o veletrhu na PLZEN.cz\" href=\"https://www.plzen.cz/2018/01/31/92951\" target=\"_blank\">https://www.plzen.cz/2018/01/31/92951</a></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><strong><a title=\"pro média\" href=\"../index.php?list=l10_05&language=lan1&lay=\" target=\"_blank\">Tiskové zprávy a info pro média ZDE</a></strong></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><br /></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><strong>6. ročník veletrhu proběhl 30. LEDNA 2018, KD PEKLO PLZEŇ, 10-18 hod</strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\">pod záštitou Evy Herinkové, náměstkyně primátora města Plzně</span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\">a Lumíra Aschenbrennera, senátora a starosty UMO 2</span></p>\r\n<p style=\"text-align: center;\"> </p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: small;\"><strong>Z ohlasů od vystavovatelů:</strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><em>\"Veletrh se nám velice líbil, reakce lidí (kandidátů hledající práci) byly opravdu zajímavé. Získali jsme 15 kontaktů na zájemce o práci, zároveň 8 životopisů. Celkově  9 uchazečů máme pozvaných na pohovor. Hodnotíme tento veletrh jako přínosný.\"<br />Irena Cuchalová, Precision Castparts CZ s.r.o.</em><br /></span></p>\r\n</div>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"> </span><br /><span style=\"font-size: small;\"> </span></p>\r\n<hr />\r\n<p style=\"text-align: center;\"><span style=\"font-size: xx-small;\"></span><span style=\"font-size: small;\"><span style=\"font-size: xx-small;\"><br />--%VLOZVIDEOFLV_180125StudioZ-Grafia4%--</span></span></p>\r\n<hr />\r\n<table style=\"width: 100%; height: auto;\" border=\"0\" cellpadding=\"10\" align=\"left\">\r\n<tbody>\r\n<tr align=\"center\" valign=\"middle\">\r\n<td style=\"width: 7%;\"> </td>\r\n<td><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/9500875.jpg\" alt=\"soubor F_A15_3469_zmensena.jpg\" width=\"380\" /> </td>\r\n<td style=\"width: 3%;\"> </td>\r\n<td>\r\n<p style=\"text-align: left;\"> <span style=\"font-size: small;\"><span style=\"font-size: small;\"><em>Hledáte práci?<br /> Poohlížíte se po lepším místě?</em><em><br /> Chcete stáž či brigádu?</em></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><br /></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: small;\"><em><span> Přijďte se osobně setkat s personalisty,</span></em></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: small;\"><em><span> porovnejte si nabídky firem v regionu.</span></em></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: small;\"><em><span><br /></span></em></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: small;\"><em><span> Dělejte to, co Vás opravdu baví!</span></em></span></p>\r\n</td>\r\n<td style=\"width: 1%;\"> </td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><span style=\"font-size: small;\"><strong>Vystavujícími budou podniky nabízející práci i vzdělávací instituce s nabídkou kurzů. </strong></span></span></strong></span></strong></span></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><strong>Veletrh je určen široké veřejnosti, těm, kteří chtějí najít či změnit práci, hledají stáž či brigádu, rekvalifikaci nebo jazykové kurzy. Je otevřen i všem studentům a absolventům vysokých a středních škol, odborných škol a učilišť.</strong></span></strong></span></p>\r\n<p><span style=\"font-size: small; color: #eb1b4c;\"><strong><span style=\"font-size: small;\"><strong>Průběžně aktualizovaný seznam vystavovatelů je k dispozici <span style=\"text-decoration: underline;\"><a href=\"../index.php?list=l10_06&language=lan1&lay=\"><span style=\"color: #eb1b4c; text-decoration: underline;\">ZDE</span></a>.</span></strong></span></strong></span></p>\r\n<p><span style=\"font-size: small;\">Připravujeme tradičně obsáhlý<a href=\"../index.php?list=l10_03&language=lan1&lay=\"><strong> doprovodný program - přednášky i poradny... </strong></a></span></p>\r\n<p><span style=\"font-size: small;\">Vstupné i celý program pro návštěvníky<strong> ZDARMA. </strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Každou hodinu slosování o ceny. </strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Vyhodnocení podniků přátelských rodinám svých zaměstnanců - viz <a href=\"../index.php?list=l02&language=lan1&lay=\">Mamma/Parent Friendly.</a><br /></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium; color: #eb1b4c;\"><strong>I když práci právě nehledáte, přijít se vyplatí!</strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><br /></span></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\">Děkujeme za záštitu nad letošním ročníkem veletrhu, kterou s radostí převzala Bc. Eva Herinková, náměstkyně primátora pro oblast školství a sociálních věcí. <br /></span></strong></span></p>\r\n<p> </p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/9300387.jpg\" alt=\"soubor Záštita 2018.jpg\" width=\"606\" height=\"426\" />  </p>\r\n<p><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><br /></span></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\">Účastí na Veletrhu práce a vzdělávání získáte:</span></strong></span></p>\r\n<ul>\r\n<li><strong><span style=\"font-size: small;\">lepší přehled o současném trhu pracovních příležitostí</span></strong></li>\r\n<li><strong><span style=\"font-size: small;\">osobní kontakt s personalisty renomovaných společností</span></strong></li>\r\n<li><strong><span style=\"font-size: small;\">nové znalosti a dovednosti účastí na doprovodném programu veletrhu<span style=\"font-size: xx-small;\"></span><br /></span></strong></li>\r\n</ul>\r\n<p><span><br />Přijďte připraveni. <strong>Přineste si svůj pracovní životopis</strong>, zkonzultujte ho s odborníky a osobně předejte personalistům!</span></p>\r\n<p><span style=\"font-size: small;\"><strong>Těšíme se na Vás!</strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong></strong>Grafia, s.r.o.</span></p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1809449.jpg\" alt=\"veletrhprace\" /></p>\r\n<p> </p>\r\n<p> </p>\r\n<p style=\"margin-top: 30px;\"><span style=\"font-size: x-small;\">Děkujeme za spolupráci:</span><a title=\"Kudyznudy.cz - odkaz\" href=\"http://www.kudyznudy.cz/\" target=\"_blank\"><img style=\"margin-right: 10px; margin-left: 10px; vertical-align: middle;\" src=\"files/1198934.jpg\" alt=\"kudyznudy\" width=\"auto\" height=\"20\" /></a></p>', '', '', 'administrator', '2019-11-13 14:23:36');
