INSERT INTO `paper` VALUES ('996', '295', 'l10_01', 'Pomáhejte s námi', '<p><span style=\"font-size: small;\"></span><span style=\"font-size: small; color: #eb1b4c;\"><strong>DĚKUJEME, DĚKUJEME, DĚKUJEME VÁM VŠEM !</strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>VYBRALO SE ÚŽASNÝCH CCA<span style=\"color: #eb1b4c;\"> 400 KS</span> STARÝCH BRÝLÍ A I DÍKY VÁM JSME OPĚT MOHLI POMOCI POTŘEBNÝM!</strong></span></p>\r\n<p> <img src=\"files/6290637.jpg\" alt=\"soubor 20180130_175818.jpg\" width=\"665\" height=\"345\" /></p>\r\n<p><em>Plné 2 krabice jste přinesli zástupcům plzeňského Lions Clubu (manželé Švarcovi - Optika Švarc). Děkujeme!<br />(po této fotografii pořízené v 17:58 ještě přiběhla paní s dalšími 2 kousky...)<br /></em></p>\r\n<p><span style=\"font-size: small;\"><strong><br /></strong></span></p>\r\n<p><span style=\"font-size: small; color: #eb1b4c;\"><strong>A jak snadné to bylo?<br /></strong></span></p>\r\n<p><span style=\"font-size: small;\">Každý, kdo chtěl, <strong>přinesl své staré brýle - sluneční, dioptrické, dětské, dámské, pánské</strong> - jakékoliv a věnoval je do sbírky potřebným.</span></p>\r\n<p><span style=\"font-size: small;\">Jako každý rok i letos spolupracujeme s Lions Clubs International a jejich prostřednictvím putují brýle do Afrických zemí, dětem, seniorům, všem, kteří si je nemohou sami zakoupit.</span></p>\r\n<p><span style=\"font-size: small;\">Brýle jsme tradičně sbírali<strong> na balkoně hlavního výstavního sálu, 30. ledna 2018 od 10:00 do 18:00 hodin v prostoru poradny \"testování zrakové kondice\".</strong></span></p>\r\n<p> </p>\r\n<p><span style=\"font-size: small;\"><strong>Jsme pyšní na letošní skvělý výsledek!<br /></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Děkujeme Vám a těšíme se na leden 2019!<br /></strong></span></p>\r\n<p> </p>\r\n<p><span style=\"font-size: small;\"><strong>Vaše Grafia</strong></span></p>\r\n<table border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p><img src=\"files/1813021.jpg\" alt=\"soubor Brýle 1.jpg\" width=\"334\" height=\"223\" /></p>\r\n</td>\r\n<td>\r\n<p><img src=\"files/1953439.jpg\" alt=\"soubor Brýle 2.jpg\" width=\"335\" height=\"223\" /></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td>\r\n<p><img src=\"files/1767269.jpg\" alt=\"soubor Brýle 4.jpg\" width=\"331\" height=\"213\" /></p>\r\n</td>\r\n<td> <img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1593778.jpg\" alt=\"soubor brýle 5.jpg\" width=\"302\" height=\"228\" /></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style=\"font-size: small;\"><strong><br /></strong></span></p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2018-10-05 15:06:21');
