INSERT INTO `paper` VALUES ('999', '298', 'l10_02', 'Nabízená pracovní místa', '<h2 style=\"text-align: left;\"><span style=\"font-size: medium;\"><strong>6. ročník veletrhu nabídl tradičně široké spektrum pracovních pozic pro všechny úrovně kvalifikací, pro muže, pro ženy:</strong></span></h2>\r\n<p><strong>Aktuálně firmy hledají:</strong></p>\r\n<table style=\"width: 100%; height: auto;\" border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td style=\"text-align: left; width: 2%;\"> </td>\r\n<td style=\"text-align: left; width: 32%;\">\r\n<p><span style=\"font-size: x-small;\">Operátory výroby</span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: xx-small;\">Techniky SMT linky</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\">Procesní inženýry</span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\">Vedoucí stroje</span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\">Obsluhy stroje</span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\">Seřizovače</span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\"><span style=\"font-size: xx-small;\">Operátory provozu laserových tiskáren</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><s