INSERT INTO `paper` VALUES ('1140', '439', 'l11', 'ROK 2019', '<div style=\"float: right;\"><span style=\"font-size: medium;\"> <strong><span style=\"font-size: small;\"> <strong> <a title=\"Veletrh práce a vzdělávání Plzeň - Klíč k příležitostem\" href=\"https://www.facebook.com/veletrhprace\" target=\"_blank\"> <img style=\"margin: 10px 70px 10px 40px; float: right;\" title=\"facebook\" src=\"files/1153903.png\" alt=\"facebook\" width=\"58\" height=\"58\" /> </a><a title=\"Veletrh práce a vzdělávání Plzeň - Klíč k příležitostem\" href=\"https://www.facebook.com/veletrhprace\" target=\"_blank\"><br /> </a> </strong></span></strong> </span></div>\r\n<div style=\"text-align: center;\"><br />\r\n<p style=\"text-align: left;\"><span style=\"font-size: x-small;\"><strong style=\"color: #e20019; font-size: medium;\">Ohlédnutí za 7. ročníkem, který proběhl 30. 1. 2019 </strong></span><strong style=\"color: #e20019; font-size: medium;\">v bývalém OD Prior v Plzni</strong></p>\r\n<div style=\"text-align: left;\"><span style=\"font-size: small; color: #000000;\"><strong style=\"font-size: small;\">Děkujeme všem, více než 2.600 návštěvníkům!</strong></span></div>\r\n<div style=\"text-align: left;\"><strong style=\"font-size: small;\"><br /></strong></div>\r\n<div style=\"text-align: left;\"><strong style=\"font-size: small;\">Fotogalerii najdete: <a title=\"fotky z veletrhu práce a vzdělávání 2019\" href=\"https://veletrhprace.rajce.idnes.cz/2019/\" target=\"_blank\"><span style=\"color: #000000;\">ZDE</span></a></strong></div>\r\n<div> </div>\r\n<p style=\"text-align: center;\"><span style=\"color: #000000;\"><strong style=\"font-size: small;\"> Živé zpravodajství z Veletrhu shlédněte na <a href=\"https://www.plzen.cz/plzensky-veletrh-prace-a-vzdelavani-klic-k-prilezitostem-vzbudil-velky-zajem-lidi/\" target=\"_blank\"><span style=\"color: #000000;\">Informačním portálu pro Plzeň a Plzeňský kraj www.plzen.cz</span></a> <br /><br /> </strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small; color: #000000;\"><em>K úspěchu veletrhu přispěl i<strong> </strong></em><em>netradiční industriální prostor</em><strong><em> <strong><em>• </em></strong></em></strong><em><a title=\"Celodenní program veletrhu\" href=\"../index.php?list=l05&language=lan1&lay=\" target=\"_blank\"><span style=\"color: #000000;\">skvělý celodenní program</span></a> <strong><em> <strong><em>• </em></strong></em></strong><em><em>slosování o zajímavé dárky <strong><em>•</em></strong><em><a title=\"Mamma/Parent Friendly\" href=\"../index.php?list=l02&language=lan1&lay=\" target=\"_blank\"><span style=\"color: #000000;\"> ocenění podnikům přátelským rodině <em><strong><em><strong><em>• </em></strong></em></strong></em></span></a><a title=\"sbírka brýlí\" href=\"../index.php?list=l07&language=lan1&lay=\" target=\"_blank\"><span style=\"color: #000000;\">sbírka starých brýlí</span></a></em></em></em></em></span></p>\r\n<p style=\"text-align: center;\"><strong style=\"font-size: small;\"><span style=\"font-size: medium;\"><strong><span><span style=\"font-size: small;\"><span style=\"font-size: xx-small;\">--%VLOZVIDEOFLV_2019-01-16 INTERVIEW BRABCOVA_600%--</span></span></span></strong></span></strong></p>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><br /></strong></span></div>\r\n<p style=\"text-align: center;\"> </p>\r\n<hr />\r\n<p style=\"text-align: center;\"><strong style=\"font-size: x-small;\"><strong><strong><br /></strong></strong></strong></p>\r\n<p style=\"text-align: center;\"><strong><span style=\"font-size: small;\">Záštitu nad ročníkem 2019 převzal <br />Mgr. Martin Baxa, primátor města Plzně.</span></strong></p>\r\n</div>\r\n<p style=\"text-align: center;\"><img src=\"files/2031716.jpg\" alt=\"Záštita VPV 2019\" /></p>', '', 'veletrh práce a vzdělávání plzeň 2019', 'administrator', '2020-01-27 18:13:42');
