INSERT INTO `paper` VALUES ('1143', '442', 'l11_01', 'Doprovodný program', '<p><span style=\"font-size: medium;\"><strong><span style=\"color: #e20019;\">Na co se můžete těšit? </span></strong></span></p>\r\n<p><span style=\"font-size: medium;\"><strong><span style=\"color: #e20019;\">I když na programu stále ještě pracujeme a může se změnit, už nyní se můžete podívat, co na Vás v lednu 2019 čeká:<br /></span></strong></span></p>\r\n<p><span style=\"font-size: medium;\"><strong>PŘEDNÁŠKY PO CELÝ DEN:</strong></span></p>\r\n<div style=\"width: 95%; margin-left: auto; margin-right: auto;\">\r\n<table border=\"0\" frame=\"border\" rules=\"all\" cellspacing=\"0\"><colgroup span=\"2\" width=\"10%\"></colgroup> <colgroup width=\"40%\"></colgroup> <colgroup width=\"\"></colgroup>\r\n<tbody>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"left\" valign=\"middle\" height=\"20\"><span style=\"color: #e20019;\"><strong>Od</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"left\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>Do</strong></span></td>\r\n<td align=\"center\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>Téma</strong></span></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" height=\"48\"><span style=\"color: #e20019;\"><strong>10:30</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\"><span style=\"color: #e20019;\"><strong>11:00</strong></span></td>\r\n<td style=\"text-align: left; padding: 2px 5px;\" align=\"left\">\r\n<p><strong>Jak se vyznat na pracovním trhu?</strong></p>\r\n<p><em>Kdy využít personální agenturu? Kde se poradit?<strong><br /></strong></em></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"58\"><span style=\"color: #e20019;\"><strong>11:15</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>11:45</strong></span></td>\r\n<td style=\"text-align: left; padding: 2px 5px;\" align=\"left\">\r\n<p><strong>Jak se připravit na pracovní pohovor?</strong></p>\r\n<p><em>Nejčastější chyby při pracovním pohovoru a jak se jich vyvarovat?</em></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"48\"><span style=\"color: #e20019;\"><strong>12:00</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>12:30</strong></span></td>\r\n<td style=\"text-align: left; padding: 0px 5px;\" align=\"left\">\r\n<p><strong><strong>„Blázníš? No a !“<br /></strong></strong><em>Ve škole i doma...</em><strong><strong><br /></strong></strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"58\"><span style=\"color: #e20019;\"><strong>12:45</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>13:15</strong></span></td>\r\n<td style=\"text-align: left; padding: 0px 5px;\" align=\"left\">\r\n<p><strong>Profesní předpoklady v písmu</strong></p>\r\n<p><em>Víte, co vše o Vás říká Vaše písmo?<br /></em></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"58\"><span style=\"color: #e20019;\"><strong>13:30</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>14:00</strong></span></td>\r\n<td style=\"text-align: left; padding: 0px 5px;\" align=\"left\"><strong>Na co dát pozor při uzavírání pracovní smlouvy?</strong><br />\r\n<p><em>Co musí a nemusí být v pracovní smlouvě a proč? Užitečné tipy a rady pro Vás.<br /></em></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"48\"><span style=\"color: #e20019;\"><strong>14:15</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>14:45</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\"><strong>Možnosti zaměstnání v zahraničí. (EURES + ÚP)<br /></strong><em>Chcete vycestovat za prací do zahraničí? Poradíme, jak na to.</em></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"78\"><span style=\"color: #e20019;\"><strong>15:00</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>15:30</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\">\r\n<p><strong>Jak nastartovat svůj vlastní business?</strong></p>\r\n<p><em>Chcete rozjet vlastní podnikání? A víte, kdo a jak Vám může pomoci?</em></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"68\"><span style=\"color: #e20019;\"><strong>15:45</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>16:15</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\">\r\n<p><strong>Jak nepřijít na mizinu?</strong></p>\r\n<p><em> Jak předejít zadlužení?</em> <em>Co je dobré vědět?</em></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"48\"><span style=\"color: #e20019;\"><strong>16:30</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>17:00</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\"><strong>„Jak se z tý práce nezbláznit?“</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<p> </p>\r\n<p><span style=\"font-size: small; color: #e20019;\"><strong><span style=\"font-size: medium;\">Poradny a další aktivity:</span> <br /></strong></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"color: #e20019;\"><strong></strong></span><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>10:00 - 18:00</strong></span> <strong>Kariérové poradenství a personální testování</strong></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: small;\"><strong></strong></span></span><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>10:00 - 18:00</strong></span> <strong>Pracovně-právní poradna</strong></span><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong></strong></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>10:00 - 18:00</strong></span> <strong>Image + brýlová poradna</strong></span><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong></strong></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>10:00 - 18:00</strong></span> <strong>FOTKY do životopisu od profesionálního fotografa</strong></span><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong></strong></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>10:00 - 18:00</strong></span> <strong>Kadeřnice a Kosmetička</strong></span><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong></strong></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>10:00 - 18:00</strong></span> <strong>Poradna pro začínající podnikatele</strong></span><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong></strong></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>14:00 - 16:00</strong></span> <strong>Grafologické poradenství</strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong></strong></span><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>10:00 - 18:00</strong></span> <strong>Testování zrakové kondice, sbírka starých brýlí</strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>10:00 - 18:00</strong></span> Poradna duševního zdraví<strong></strong></span></strong></span></p>\r\n<p> </p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong>13:00 </strong></span><strong>Slavnostní předávání ocenění Mamma/Parent Friendly za rok 2018<br /></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small; color: #e20019;\"><strong>VEŠKERÝ PROGRAM JE PRO NÁVŠTĚVNÍKY VELETRHU ZDARMA!</strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small; color: #e20019;\"><strong>PŘIJĎTE, NUDIT SE URČITĚ NEBUDETE...<br /></strong></span></p>', '', '', 'administrator', '2019-10-15 15:48:27');
INSERT INTO `paper` VALUES ('1144', '443', 'l11_01', 'Doprovodný program', null, '', null, 'administrator', '2019-10-15 15:48:27');
