INSERT INTO `paper` VALUES ('1296', '595', 'l11_06', 'Nabízená pracovní místa', '<h1 style=\"text-align: center;\"><span style=\"font-size: medium;\"><strong>Seznam pracovních pozic Veletrhu práce a vzdělávání Klíč k příležitostem</strong></span></h1>\r\n<h1 style=\"text-align: center;\"><span style=\"font-size: medium;\"><strong>30. 1. 2019 <br /></strong></span></h1>\r\n<p> </p>\r\n<table border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p><span style=\"font-size: x-small;\">Příprava technické dokumentace</span><br /><span style=\"font-size: x-small;\">Obsluha CNC obráběcího centra</span><br /><span style=\"font-size: x-small;\">Mechanik CNC</span><br /><span style=\"font-size: x-small;\">Pracovník mezioperační kontroly FMC</span><br /><span style=\"font-size: x-small;\">Recepční</span><br /><span style=\"font-size: x-small;\">Referent řízení výroby</span><br /><span style=\"font-size: x-small;\">Mistr výroby</span><br /><span style=\"font-size: x-small;\">vedoucí vstupní kontroly</span><br /><span style=\"font-size: x-small;\">technik vstřikování plastů</span><br /><span style=\"font-size: x-small;\">referent zkušební laboratoře</span><br /><span style=\"font-size: x-small;\">dělník v elektrotechnice – Chotěšov</span><br /><span style=\"font-size: x-small;\">seřizovač / mechanik / střihač – Chotěšov</span><br /><span style=\"font-size: x-small;\">skladník s VZV / manipulant – Chotěšov</span><br /><span style=\"font-size: x-small;\">obráběč v nástrojárně / seřizovač CNC strojů – Chotěšov</span><br /><span style=\"font-size: x-small;\">Pokladní/prodavač</span><br /><span style=\"font-size: x-small;\">Zástupce vedoucího prodejny</span><br /><span style=\"font-size: x-small;\">Brigádník Pokladní/prodavač</span><br /><span style=\"font-size: x-small;\">Třídič/ka</span><br /><span style=\"font-size: x-small;\">Strojník</span><br /><span style=\"font-size: x-small;\">Seřizovač kontrolních automatů</span><br /><span style=\"font-size: x-small;\">Manipulant</span><br /><span style=\"font-size: x-small;\">Operátor výroby – brusič, leštič</span><br /><span style=\"font-size: x-small;\">Operátor výroby – kontrola, montáž</span><br /><span style=\"font-size: x-small;\">Frézař – obsluha CNC</span></p>\r\n<p><span style=\"font-size: x-small;\">Dělník ve výrobě<br />Skladník</span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Kontrola kvality</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Operátor zpracování zboží<br />Manipulant<br />Mistr<br />Referent personálního oddělení<br />Operátor zpracování zboží<br />Manipulant</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Obsluha/vedoucí stroje<br />Skladník</span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"></span></span></span></span></span></span></span></span> <span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Řidič, sk.C<br />Pracovník/ce třídění balíkových zásilek<br />Pracovník/ce třídění listovních zásilek</span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"></span></span></span></span></span></span></span></span>kalkulant - rozpočtář<br />project manager technického zaměření</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">svářeč- zámečník</span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"></span></span></span></span></span></span></span></span></span></span>Programátor/vývojář<br />Tiskař<br />Pomocník tiskaře</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Sachbearbeiter/in Klärfal<br />Sachbearbeiter/in Qualität<br />Sachbearbeiter/in Auftragssteuerung</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Pracovník ve výrobě<br />Lisař<br />Skladník<br />Konstruktér<br />Referent expedičního oddělení<br />Technik prototypové dílny<br />Vedoucí prototypové dílny</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Inzertní poradce po telefonu</span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><br /></span></span></p>\r\n</td>\r\n<td>\r\n<p><span style=\"font-size: x-small;\">Automechanik</span><br /><span style=\"font-size: x-small;\">Pracovník ručního mytí vozidel</span><br /><span style=\"font-size: x-small;\">Specialista finančních služeb</span><br /><span style=\"font-size: x-small;\">Nákupčí automobilů</span><br /><span style=\"font-size: x-small;\">Prodejce automobilů</span><br /><span style=\"font-size: x-small;\">Pracovník podpory prodeje</span></p>\r\n<p><span style=\"font-size: x-small;\">Specialista PLC a elektrických systémů (m/ž)</span><br /><span style=\"font-size: x-small;\">Engineering Specialist for Mechanical Systems and Solutions</span><br /><span style=\"font-size: x-small;\">Engineering Specialist for Automation and Storage Systems</span><br /><span style=\"font-size: x-small;\">Specialista pro automatické a skladové systémy (m / ž)</span><br /><span style=\"font-size: x-small;\">Client Support with German and English</span><br /><span style=\"font-size: x-small;\">Elektrotechnik / Elektrotechnička</span><br /><span style=\"font-size: x-small;\">Údržbář strojů (m/ž) - ranní a odpolední směna!</span><br /><span style=\"font-size: x-small;\">Engineering Specialist for PLC and Electrical Systems (m/w)</span><br /><span style=\"font-size: x-small;\">Specialista inženýringu pro mechanické systémy a zařízení</span><br /><span style=\"font-size: x-small;\">Credit Controller with French</span><br /><span style=\"font-size: x-small;\">Mistr svařovny</span><br /><span style=\"font-size: x-small;\">Programátor pálicích strojů</span><br /><span style=\"font-size: x-small;\">Obsluha svařovacích robotů</span><br /><span style=\"font-size: x-small;\">Programátor svařovacích robotů</span><br /><span style=\"font-size: x-small;\">Svářeč – zámečník</span><br /><span style=\"font-size: x-small;\">Kontrolor výroby</span><br /><span style=\"font-size: x-small;\">Údržbář</span><br /><span style=\"font-size: x-small;\">Lakýrník</span></p>\r\n<p><span style=\"font-size: x-small;\">Obsluha CNC</span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Údržbář<br />Elektrikář</span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Mistr/ová výrobního provozu<br />Pracovník IT oddělení<br />Expedient hotových výrobků<br />Řidič VZV<br />Pracovník údržby – zámečník<br />Pracovníky do potravinářské výroby </span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">IT technik junior</span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Předák</span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Doručovatel/ka listovní<br />Kurýr/ka balíkových zásilek<br />Klientský/á pracovník/ce</span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">konstruktér ocelových konstrukcí<br />obráběč CNC<br />lakýrník</span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Seřizovač knihárenských strojů<br />Operátor CTP (kopista)<br />Skladník</span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Řidič VZV<br />Trenér</span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Montážní dělník</span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Procesní inženýr<br />Asistentka údržby<br />SAP konzultant<br />HR senior specialista vzdělávání<br />Brigádník v administrativě</span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Vývojář<br />Projektový manažer</span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\"><span style=\"font-size: x-small;\">Redaktor<br /></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n</td>\r\n<td><span style=\"font-size: x-small;\"> </span></td>\r\n</tr>\r\n<tr>\r\n<td> </td>\r\n<td> </td>\r\n<td> </td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p> </p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\">Přineste si s sebou svůj profesní životopis a využijte možnosti osobního setkání s personalisty významných zaměstnavatelů v regionu.</span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\">Seznam zaměstavatelů, které můžete na veletrhu navštívit naleznete <strong><a href=\"../index.php?list=l11_04&language=lan1&lay=\">ZDE</a></strong></span></p>\r\n<p> </p>\r\n<p> </p>\r\n<p><span style=\"font-size: x-small;\"><em>Stránka je průběžně aktualizována.</em></span></p>', '', '', 'administrator', '2019-10-11 11:13:24');
