INSERT INTO `paper` VALUES ('1299', '598', 'l12', 'Rok 2020', '<div><br />\r\n<p> <img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/1779663.jpg\" alt=\"soubor VPV2020spolecna.jpg\" width=\"600\" /></p>\r\n<div style=\"float: right;\"><a title=\"Veletrh práce a vzdělávání Plzeň - Klíč k příležitostem\" href=\"https://www.facebook.com/veletrhprace\" target=\"_blank\"> <img style=\"margin: 10px 70px 10px 15px; float: right;\" title=\"facebook\" src=\"files/1153903.png\" alt=\"facebook\" width=\"58\" height=\"58\" /> </a></div>\r\n<div>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small; font-weight: bold;\">Jak si stojíte na trhu práce? Veletrh dal návštěvníkům odpověď!<br /></span></p>\r\n</div>\r\n<div style=\"text-align: center;\">\r\n<h2><span style=\"font-size: small;\"><strong>8. ročník  VELETRHU PRÁCE A VZDĚLÁVÁNÍ</strong></span></h2>\r\n<p><span style=\"font-size: small;\">proběhl ve středu, 29. ledna 2020 </span></p>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><span style=\"color: #000000;\">Fotografie z akce průběžně zpracováváme a postupně přibývají <span style=\"color: #e20019;\"><a style=\"font-size: 1.2em;\" title=\"Fotky z veletrhu 2020\" href=\"https://veletrhprace.rajce.idnes.cz/Veletrh_prace_a_vzdelavani_2020\" target=\"_blank\"><span style=\"color: #e20019;\">ZDE</span></a></span>, pokud jste se nenašli dnes, můžete se najít třeba za pár dnů...</span></strong></span></div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><br /></strong></span></div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><a title=\"Nabízená pracovní místa\" href=\"../index.php?list=l12_05&language=lan1&lay=\" target=\"_blank\">Stovky pracovních míst</a> nabídly 4 desítky zaměstnavatelů - více<a title=\"Zaměstnavatelé na veletrhu\" href=\"../index.php?list=l12_04&language=lan1&lay=\" target=\"_blank\"> ZDE</a></strong><strong><a title=\"Celodenní program veletrhu\" href=\"../index.php?list=l05&language=lan1&lay=\" target=\"_blank\"><br /></a></strong></span></div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><br /></strong></span></div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><a title=\"Celodenní program veletrhu\" href=\"../index.php?list=l12_01&language=lan1&lay=\" target=\"_blank\">Celodenní program přinesl přednášky, poradny i služby</a> zdarma - více <a title=\"Celodenní program veletrhu\" href=\"../index.php?list=l12_01&language=lan1&lay=\" target=\"_blank\">ZDE<br /></a></strong><strong></strong></span></div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><br /></strong></span></div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong>Ocenění <a title=\"Mamma/Parent Friendly\" href=\"../index.php?list=l02&language=lan1&lay=\" target=\"_blank\">Mamma/Parent Friendly</a> převzaly 4 firmy - více <a title=\"Mamma/Parent Friendly\" href=\"../index.php?list=l02&language=lan1&lay=\" target=\"_blank\">ZDE <br /></a></strong><strong></strong></span></div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong><br /></strong></span></div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: small;\"><strong>781 st<a title=\"sbírka brýlí\" href=\"../index.php?list=l12_02&language=lan1&lay=\" target=\"_blank\">arých brýlí putuje do sbírky</a> Lions Clubu  - více <a title=\"sbírka brýlí\" href=\"../index.php?list=l12_02&language=lan1&lay=\" target=\"_blank\">ZDE</a></strong></span></div>\r\n<p> </p>\r\n</div>\r\n</div>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small; color: #333333;\"><span style=\"font-size: xx-small;\"> --%VLOZVIDEOFLV_200127 Studio Z_Grafia_Veletrh_prace_2020%-- </span> <br /> </span></p>\r\n<p style=\"text-align: center;\"> </p>\r\n<hr />\r\n<p style=\"text-align: center;\"><strong style=\"font-size: small; text-align: center;\">Záštitu nad 8. ročníkem veletrhu </strong><strong style=\"font-size: small;\">převzali </strong></p>\r\n<p style=\"text-align: center;\"><strong style=\"font-size: small;\">Mgr. Martin Baxa, primátor města Plzně <br /></strong><strong style=\"font-size: small;\">a Ing. Lumír Aschenbrenner, senátor a starosta UMO 2.</strong></p>\r\n<p style=\"text-align: center;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"files/8622094.jpg\" alt=\"soubor zastita_VPV_edit.jpg\" width=\"600\" /></p>\r\n<p> </p>', '', '', 'administrator', '2021-06-21 14:35:41');
