INSERT INTO `paper` VALUES ('1302', '601', 'l12_01', 'Doprovodný program', '<p style=\"text-align: center;\"><span style=\"font-size: medium; color: #e20019;\"><strong>Jaký byl doprovodný program roku 2020?</strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium; color: #e20019;\"><strong> Tradičně skvělý - plná přednášková místnost po celý den, velký zájem o veškeré poradenské aktivity.<br /></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\"><br /></span></span></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: medium;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\">Poradny po celý den 10:00 - 18:00 hodin</span></span></strong></span></p>\r\n<p><span style=\"font-size: medium;\"><span style=\"font-size: small;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\">Kariérové poradenství a personální testování</span></span></strong></span><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\"><span style=\"font-size: small; color: #000000;\"></span><span style=\"font-size: small; color: #000000;\"></span><span style=\"font-size: small; color: #000000;\"><br />Jak mít ještě lepší životopis? Co změnit? Otestujte svoje pracovní předpoklady - krátké testy s vyhodnocením na místě.</span></span></span><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\"><br /></span></span></strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\">Pracovně-právní poradna</span></span></strong></span><span style=\"font-size: small; color: #000000;\"><br />Na co si dát pozor při uzavírání pracovní smlouvy? Kde najdu příslušná znění zákonů a pravidel pro pracovně-právní vztahy?</span></p>\r\n<p><span style=\"color: #000000; font-size: small;\"><strong><span style=\"color: #e20019;\">Poradna pro začínající podnikatele</span></strong></span><span style=\"font-size: small; color: #000000;\"><strong><br /></strong>Uvažujete o vlastní firmě? Chcete začít podnikat? Ověřte si a poraďte se, kde najít potřebné informace a jak nastartovat svůj vlastní business.<br /></span></p>\r\n<p><span style=\"color: #000000; font-size: small;\"><strong><span style=\"color: #e20019;\">Kadeřnice, kosmetičky</span></strong></span><span style=\"font-size: small; color: #000000;\"><strong><br /></strong>Nechte se hýčkat - učesat, nalíčit a poté navštivte třeba fotografa nebo svého ideálního zaměstnavatele.</span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"color: #e20019;\">FOTKY do životopisu</span><br /></strong></span><span style=\"color: #000000;\"> </span><span style=\"color: #000000;\">Profesionální foto do Vašeho životopisu, fotku Vám zašleme e-mailem. Jste ještě rozespalí a neučesaní? Nevadí - před fotografováním navštivte naše kadeřnice a kosmetičky a pak už se není čeho obávat...<br /></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"color: #e20019;\">FOTOKOUTEK - Crazy foto</span><br /></strong></span><span style=\"color: #000000;\">Pobavte sebe i své přátele na sociálních sítích veselou CRAZY fotkou - sdílejte, lajkujte, bavte se...<br /></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong></strong></span><span style=\"color: #000000;\"><strong><span style=\"color: #e20019;\">Měření tlaku, ukázky první pomoci</span></strong></span></span><span style=\"font-size: small; color: #000000;\"><strong><br /></strong>Jak si poradit v neočekávané situaci? Umíte poskytnout první pomoc? Profesionální ukázky první pomoci, měření tlaku...<strong><br /></strong></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"color: #e20019;\">Testování zrakové kondice</span><br /></strong></span><span style=\"color: #000000;\">Otestujte svoji zrakovou kondici, nechte si poradit, co Vaše oči potřebují.<br /></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"color: #e20019;\">Image a brýlová poradna</span><br /></strong></span><span style=\"color: #000000;\">\"Sluší mi ty brýle?\" \"Hodí se to k mému typu?\" Profesionální poradenství - vyzkoušejte, konzultujte, nestyďte se.<br /></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"color: #e20019;\">Poradna duševního zdraví</span><br /></strong></span><span style=\"color: #000000;\">Trápí Vás konkrétní poruchy, máte problém v rodině, ve škole, v práci? Poradna duševního zdraví je zde pro Vás.<br /><strong></strong></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><br /></strong></span></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"font-size: medium;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\">PŘEDNÁŠKY A INSPIRACE PRO VÁS</span></span></strong></span></strong></span></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"font-size: medium;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\"><br /></span></span></strong></span></strong></span></span></p>\r\n<table style=\"border-color: #eeeff0; border-width: 0px; border-style: solid;\" border=\"0\" frame=\"border\" rules=\"all\" cellspacing=\"5\" cellpadding=\"5\" align=\"center\">\r\n<tbody>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"left\" valign=\"middle\" height=\"20\"><span style=\"color: #e20019;\"><strong>Od</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"left\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>Do</strong></span></td>\r\n<td align=\"center\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>Téma</strong></span></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" height=\"48\"><span style=\"color: #e20019;\"><strong>10:30</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\"><span style=\"color: #e20019;\"><strong>11:00</strong></span></td>\r\n<td style=\"text-align: left; padding: 2px 5px;\" align=\"left\">\r\n<p><strong>Na co dát pozor při uzavírání pracovní smlouvy?</strong></p>\r\n<p>Co musí a nemusí být v pracovní smlouvě a proč? Užitečné tipy a rady pro Vás.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"58\"><span style=\"color: #e20019;\"><strong>11:15</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>11:45</strong></span></td>\r\n<td style=\"text-align: left; padding: 2px 5px;\" align=\"left\">\r\n<p><strong>Jak se připravit na pracovní pohovor?</strong></p>\r\n<p>Nejčastější chyby při pracovním pohovoru a jak se jich vyvarovat?</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"48\"><span style=\"color: #e20019;\"><strong>12:00</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>12:30</strong></span></td>\r\n<td style=\"text-align: left; padding: 0px 5px;\" align=\"left\">\r\n<p><strong><strong>Umíte si poradit? Ukázka první pomoci a resuscitace v praxi.</strong></strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"58\"><span style=\"color: #e20019;\"><strong>12:45</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>13:15</strong></span></td>\r\n<td style=\"text-align: left; padding: 0px 5px;\" align=\"left\">\r\n<p><strong>„Blázníš? No a !“</strong></p>\r\n<p>Ve škole i doma.</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"58\"><span style=\"color: #e20019;\"><strong>13:30</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>14:00</strong></span></td>\r\n<td style=\"text-align: left; padding: 0px 5px;\" align=\"left\"><strong><strong>Domluvíte se ve své profesi anglicky/německy? <br /></strong></strong>Využijte možnosti intenzívních kurzů odborné AJ/NJ v Plzni.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"48\"><span style=\"color: #e20019;\"><strong>14:15</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>14:45</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\"><strong>Možnosti zaměstnání v zahraničí. (EURES + ÚP)<br /></strong>Chcete vycestovat za prací do zahraničí? Poradíme, jak na to.</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"78\"><span style=\"color: #e20019;\"><strong>15:00</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>15:30</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\">\r\n<p><strong>Jak nastartovat svůj vlastní business?</strong></p>\r\n<p><em>Chcete rozjet vlastní podnikání? A víte, kdo a jak Vám může pomoci?</em></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"68\"><span style=\"color: #e20019;\"><strong>15:45</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>16:15</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\">\r\n<p><strong>Prezentujte (nejen sebe) líp než Steve Jobs...</strong></p>\r\n<p>Zbavte se trémy a buďte sví při jakékoliv prezentaci</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"48\"><span style=\"color: #e20019;\"><strong>16:30</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>17:00</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\"><strong>„Jak se z tý práce nezbláznit?“</strong></td>\r\n</tr>\r\n<tr>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\" height=\"48\"><span style=\"color: #e20019;\"><strong>17:15</strong></span></td>\r\n<td style=\"text-align: center;\" align=\"right\" valign=\"middle\"><span style=\"color: #e20019;\"><strong>17:45</strong></span></td>\r\n<td style=\"padding: 2px 5px;\" align=\"left\"><strong>Mýty a fakta o násilí</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p style=\"text-align: left;\"><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"font-size: medium;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\"><br /></span></span></strong></span></strong></span></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"font-size: medium;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\">VŠE BYLO PRO NÁVŠTĚVNÍKY ZDARMA...<br /></span></span></strong></span></strong></span></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><span style=\"color: #000000;\"><strong><span style=\"font-size: medium;\"><strong><span style=\"color: #eb1b4c;\"><span style=\"color: #e20019;\">TĚŠÍME SE NA VÁS ZASE ZA ROK!<br /></span></span></strong></span></strong></span></span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-size: x-small; color: #000000;\">Změna programu vyhrazena.<strong><strong><br /></strong></strong></span></p>', '', '', 'administrator', '2021-06-21 13:52:31');
INSERT INTO `paper` VALUES ('1303', '602', 'l12_01', 'Doprovodný program', null, '', null, 'administrator', '2021-06-21 13:52:31');
