INSERT INTO `paper` VALUES ('1311', '610', 'l12_04', 'Seznam vystavovatelů', '<p style=\"text-align: center;\"><span style=\"color: #000000; font-size: medium;\"><strong>29. ledna 2020 od 10:00 do 18:00 vystavovali:<br /></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"color: #000000; font-size: medium;\"><strong>Pořadatel akce: <a href=\"http://www.grafia.cz/\">Grafia, s.r.o.</a></strong></span></p>\r\n<p style=\"text-align: left;\"><span style=\"color: #000000; font-size: medium;\"><strong>Vystavovatelé </strong>(v abecedním pořadí)<strong>:<br /></strong></span></p>\r\n<p><span style=\"font-size: small;\"><a href=\"https://www.4flow.com/careers.html\" target=\"_blank\"><strong>4flow management GmbH organizační složka</strong></a></span><br /><span style=\"font-size: small;\"><a href=\"https://www.pracevefabce.cz/prace-ve-fabce/\" target=\"_blank\"><strong>ASSA ABLOY ES Production s.r.o.</strong></a></span><br /><span style=\"font-size: small;\"><a href=\"https://kariera.aaaauto.cz/\" target=\"_blank\"><strong>AURES Holdings a.s.</strong></a></span><br /><a href=\"http://www.canpack.eu/?page_id=1339\" target=\"_blank\"><span style=\"font-size: small;\"><strong>CANPACK ČR<br /></strong></span></a><a href=\"https://www.domovinka.cz/\"><span style=\"font-size: small;\"><strong>DOMOVINKA - sociální služby, o.p.s.<br /></strong></span></a><a href=\"https://www.gasos-ro.cz/web/\" target=\"_blank\"><span style=\"font-size: small;\"><strong>Gymnázium a Střední odborná škola Rokycany</strong></span></a><br /><span style=\"font-size: small;\"><a href=\"https://www.hutchinson.com/en/talents\" target=\"_blank\"><strong></strong><strong>HUTCHINSON s.r.o.</strong></a></span><br /><span style=\"font-size: small;\"><a href=\"https://www.carrier.com/commercial-refrigeration/cs/cz/careers/\" target=\"_blank\"><strong>Carrier Refrigeration Operation Czech Republic s.r.o.</strong></a></span><br /><span style=\"font-size: small;\"><a href=\"https://www.tvojebudoucn