INSERT INTO `paper` VALUES ('1314', '613', 'l12_05', 'Nabízená pracovní místa', '<p style=\"text-align: center;\"><strong><span style=\"font-size: small; color: #e20019;\">Výběr nabízených pracovních míst na 8. ročníku Veletrhu práce a vzdělávání:</span><br /></strong></p>\r\n<p> </p>\r\n<table border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p><span style=\"font-size: small;\">Technik pro podporu výroby a inženýringu (m/ž), Štěnovice<br />Pracovník zákaznického servisu s němčinou (m/ž) <br />IT Help Desk Agent with English Plzeň (m/f) <br />Sales Order Administrator with French and English (m/f) <br />Credit Controller with English (m/f) <br />Financial Controller with English (m/f) <br />Credit & Cash Collection Team Leader - GE + EN (m/f)<br />Vedoucí skupiny ve skladu - pouze odpolední směna (m/ž), Úherce/Nýřany<br />Řidič VZV/Retrak (m/ž), Úherce/Nýřany<br />Směnový mistr/ová kvality<br />Zástupce/kyně směnového mistra ve výrobě<br />Zástupce/kyně směnového mistra ve kvalitě<br />Páječ/ka<br />Logistik<br />Kontrolor/ka kvality</span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\">Skladník<br />Obsluha poloautomatického svařovacího stroje</span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\">Obsluha stroje<br />Technik přípravy tisku<br />Asistentka vedoucího výroby<br />Kvality kontroler<br />Kvality statistik</span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Logistics Specialist (Full-Time / Part-Time)<br />Transportation Cost Specialist (Full-Time / Part-Time)</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Quality Engineer</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Datový analytik</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">PR Specialista</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Projektový koordinátor</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Specialista prodeje produktů</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Elektronik - strojní programátor</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Elektrikář/ka do čistých výrobních prostor</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Logistics Specialist<br />Customer Care Specialist</span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Working Students </span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Všeobecná zdravotní sestra</span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Pracovník v sociálních službách<br /></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n</td>\r\n<td>\r\n<p><span style=\"font-size: small;\">Elektroúdržbář/ka<br />Strojní zámečník<br />Výrobní inženýr/ka<br />Inženýr/ka v oddělení kvality<br />Senior konstruktér/ka<br />Vývojový inženýr/ka<br />Specialista/ka na optimalizaci nových vývojových projektů<br />Trainee v oddělení vývoje<br />Trainee v oddělení výrobního inženýringu<br />Mechaniker (Mechanik)<br />SPS-Programmierer (Programátor systémů PLC)<br />Informatiker (Informatik)<br />Elektriker (Elektrotechnik)<br />Bauleiter Elektro + Mechanik </span></p>\r\n<p><span style=\"font-size: small;\">Lisař/ka</span></p>\r\n<p><span style=\"font-size: small;\">Specialist(k)a správy produktových dat s AJ/NJ</span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Obsluha čističky odpadních vod<br />Nástrojař<br />Údržbář<br />Elektronik<br />Elektrikář</span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Laboratorní technik</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">HR Generalist<br />Customer Care Specialist (Full-Time / Part-Time)</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Referent</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Finanční kontrolor</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Technik řídících systémů strojů</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Specialista údržby</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Obchodník</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Řidič/ka</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Montér/ka zařízení a náčiní do čistých výrobních prostor</span></span></span></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\"><span style=\"font-size: small;\">Human Resources Generalist<br />Transportation Cost Specialist<br style=\"font-size: small;\" /></span></span></span></span></span></span></span></span></span></span></span></span></p>\r\n</td>\r\n<td><span style=\"font-size: x-small;\"> </span></td>\r\n</tr>\r\n<tr>\r\n<td> </td>\r\n<td> </td>\r\n<td> </td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p> </p>\r\n<p><strong><span style=\"font-size: small;\">Každý rok je nabídka pracovních míst jiná a vždy pestrá.<br /></span></strong></p>\r\n<p> </p>', '', '', 'administrator', '2021-06-21 13:52:52');
