INSERT INTO `paper` VALUES ('1317', '616', 'l13', 'Ukraina', '<p style=\"text-align: center;\"><span style=\"font-size: large; font-family: verdana, geneva;\"><strong><span style=\"color: #e20019;\">ЯРМАРОК ПРАЦІ І ОСВІТИ</span></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: large; font-family: verdana, geneva;\"><strong><span style=\"color: #e20019;\">Ключ до можливостей&reg;</span></strong></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-family: verdana, geneva; font-size: large;\">&nbsp;<strong><strong>вільний вхід</strong></strong></span></p>\r\n<p style=\"float: right; margin-top: 25px;\"><span style=\"font-family: verdana, geneva;\"><img src=\"_files/najdisi/files/1349340.jpg\" alt=\"pr&aacute;ce\"></span></p>\r\n<p style=\"text-align: left;\"><strong style=\"font-family: verdana, geneva;\">28. 1. 2026, 10:00 - 18:00</strong></p>\r\n<p style=\"text-align: left;\"><span style=\"font-family: verdana, geneva;\"><strong>TJ Lokomotiva, &Uacute;slavsk&aacute; 75, Plzeň</strong></span></p>\r\n<p><span style=\"font-family: verdana, geneva;\">Ви шукаєте роботу? Вам потрібні безкоштовні курси?</span></p>\r\n<p><span style=\"font-family: verdana, geneva;\">Приходьте до нас за гарною роботою.</span><br><span style=\"font-family: verdana, geneva;\">Домовитись вам допоможуть перекладачі.</span></p>\r\n<ul>\r\n<li><span style=\"font-family: verdana, geneva;\">працевлаштування</span></li>\r\n<li><span style=\"font-family: verdana, geneva;\">стажування</span></li>\r\n<li><span style=\"font-family: verdana, geneva;\">робота за кордоном</span></li>\r\n<li><span style=\"font-family: verdana, geneva;\">перепідготовка</span></li>\r\n<li><span style=\"font-family: verdana, geneva;\">професійні курси</span></li>\r\n<li><span style=\"font-family: verdana, geneva;\">консультування</span></li>\r\n<li><span style=\"font-family: verdana, geneva;\">десятки роботодавців</span></li>\r\n<li><span style=\"font-family: verdana, geneva;\">сотні робочих місць</span></li>\r\n<li>Український куточок</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n<!--\r\n<p><a href=\"_files/najdisi/files/1320818.jpg\" target=\"_blank\" rel=\"noopener\">листівки -&nbsp;більше інформації про ярмарок (клацніть)</a></p>\r\n<p><a href=\"_files/najdisi/files/4338589.jpg\" target=\"_blank\" rel=\"noopener\">листівки -&nbsp;більше інформації про курси (клацніть)</a></p>\r\n<p><span style=\"font-family: verdana, geneva;\">&nbsp;</span></p>\r\n<p><span style=\"font-family: verdana, geneva;\"><a target=\"_blank\" rel=\"noopener\">ціла карта (клацніть)</a></span></p> -->\r\n<p style=\"text-align: center;\"><a target=\"_blank\" rel=\"noopener\"><img src=\"_files/najdisi/files/2775287.jpg\" alt=\"mapa\" width=\"100%\"></a></p>\r\n<p><img src=\"_files/najdisi/files/1220346.jpg\" alt=\"kol&aacute;ž\" width=\"100%\"></p>\r\n<p>&nbsp;</p>', '', '', 'kasl2405', '2025-12-19 12:25:51');
