INSERT INTO `paper` VALUES ('1320', '619', 'l14', 'ROK 2013', '<p style=\"text-align: center;\"><span style=\"color: #000000;\">Společnost Grafia, s.r.o. spolu s partnery děkují za účast a podporu</span></p>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: medium;\">Veletrhu práce a vzdělávání</span></h2>\r\n<p style=\"text-align: center;\"><span style=\"color: #000000;\">Termín a místo konání: 23. ledna 2013 <span style=\"color: #000000;\">v Plzni </span><br />v kulturním domě Peklo 10.00 - 18.00 hod<br /></span></p>\r\n<p style=\"text-align: center;\"> Partneři veletrhu:</p>\r\n<p style=\"text-align: center;\">  <strong>    Úřad práce ČR – krajská pobočka v Plzni</strong></p>\r\n<p style=\"text-align: center;\"><strong>   Západočeská univerzita v Plzni</strong></p>\r\n<p style=\"text-align: center;\"><strong>      Hospodářská komora ČR</strong></p>\r\n<p style=\"text-align: center;\"><strong></strong> </p>\r\n<p><span style=\"font-size: small;\">Cílem veletrhu bylo <strong>pomoci rozhýbat pracovní trh</strong> v Plzeňském kraji a dát zaměstnavatelům a jejich potenciálním zaměstnancům příležitost ke společnému setkání. Zároveň veletrh informoval o <strong>možnostech vzdělávání dospělých</strong> v Plzeňském kraji.</span></p>\r\n<p>Veletrhu se zúčastnilo více než 3000 návštěvníků ze všech věkových i vzdělanostních skupin. </p>\r\n<p><span style=\"font-size: small;\">Veletrh byl určen <strong>všem, kdo mají zájem získat či  změnit zaměstnání. Na své si přišli i zájemci o brigády. </strong></span></p>\r\n<p><span style=\"font-size: small;\"><strong>VSTUP PRO NÁVŠTĚVNÍKY BYL ZDARMA v celém rozsahu <a href=\"../index.php?list=l05&language=lan1&lay=\">programu</a>.</strong></span></p>\r\n<p><span style=\"font-size: small;\">Doprovodným programem akce byl <strong>přednášky pořádané pro účastníky</strong>. Po celý den také bylo zdarma k dispozici <strong>i</strong><strong>ndividuální poradenství</strong> v oblasti vzdělávání a trhu práce.</span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\">Všichni návštěvníci veletrhu mohli <strong>zdarma využít personální testování</strong>, z něhož si odnesli protokol s výsledky, který mohou přiložit k životopisu zasílanému zaměstnavateli. V rámci veletrhu mohli navštívit i <strong>image poradnu</strong> zaměřenou na to, jak se nejvhodněji upravit na pracovní pohovor.</span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><br /></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><br /></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><br /></span></span></p>\r\n<p><span style=\"font-size: small;\"><span style=\"font-size: small;\"><br /></span></span></p>', '', '', 'jab1408', '2019-10-10 12:26:11');
