INSERT INTO `paper` VALUES ('1323', '622', 'l14_02', 'Partneři', '<p><strong>Organizátor: </strong></p>\r\n<p><strong></strong> </p>\r\n<p><strong>   Grafia, společnost s r.o., Plzeň</strong><br /><strong></strong></p>\r\n<p><strong></strong> </p>\r\n<p><strong>Partneři:</strong></p>\r\n<ul>\r\n<li>Úřad práce ČR v - krajská pobočka v Plzni</li>\r\n<li>Západočeská univerzita v Plzni</li>\r\n<li>Hospodářská komora ČR</li>\r\n</ul>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:54:45');
