INSERT INTO `paper` VALUES ('1326', '625', 'l14_03', 'Pro vystavovatele', '<p><span style=\"font-size: small;\">Společnost Grafia, s.r.o. spolu s partnery si Vás dovoluje pozvat jako vystavovatele na Veletrh práce a vzdělávání pod názvem Klíč k příležitostem, který se bude konat 23. ledna 2013  od 10,00 hod do 18,00 hod v kulturním domě Peklo v Plzni.</span></p>\r\n<p><span style=\"font-size: small;\">Naším cílem je zajistit co největší účast firem, a proto jsme <strong>„zmrazili“ ceny na minimum</strong>. Pro každého zaměstnavatele účast představuje jen minimální finanční zátěž – náklady nepřevyšují cenu běžné inzerce jedné pracovní pozice v tisku.</span></p>\r\n<p><span style=\"font-size: small;\">Návštěvníky budou všichni ti, kteří hledají práci či brigádu – lidé hledající jiné zaměstnání, studenti posledních ročníků středních škol se svými učiteli, vysokoškoláci, lidé registrovaní jako zájemci či uchazeči o zaměstnání. V takovéto podobě v západních Čechách žádný podobný veletrh ještě neproběhl.</span><br /><br /><strong><span style=\"font-size: small;\">Účastí na Veletrhu práce a vzdělávání získáte:</span></strong></p>\r\n<ul>\r\n<li><span style=\"font-size: small;\">osobní kontakt s uchazeči o zaměstnání</span></li>\r\n<li><span style=\"font-size: small;\">setkání se studenty středních škol a Západočeské univerzity v Plzni</span></li>\r\n<li><span style=\"font-size: small;\">možnost prezentovat Vaši firmu před širokým publikem</span></li>\r\n<li><span style=\"font-size: small;\">reklamu v propagačních materiálech veletrhu</span></li>\r\n</ul>\r\n<p><br /><strong>Jak se přihlásit na veletrh?</strong><br /><br />Kontaktujte nás na telefonním čísle 774 484 863 nebo e-mailem: <a href=\"mailto:rozsafny@grafia.cz\">kuralova@grafia.cz</a>.</p>\r\n<p>Podmínky účsti Vám zašleme e-mailem.</p>\r\n<p> </p>\r\n<p>Udělejte si čas pro tuto jedinečnou příležitost.</p>\r\n<p><strong>Ukažte, že jste v regionu!</strong></p>\r\n<p><strong><span style=\"font-size: small;\"></span></strong> </p>\r\n<p><strong><span style=\"font-size: small;\"></span></strong> </p>', '', '', 'jab1408', '2013-12-10 12:31:20');
