INSERT INTO `paper` VALUES ('1329', '628', 'l14_04', 'Pro návštěvníky', '<p><span style=\"font-size: small;\">Hledáte práci?<br />Poohlížíte se po lepším místě?<br />Přijďte se osobně seznámit s budoucím zaměstnavatelem na veletrh!</span></p>\r\n<p><span style=\"font-size: small;\">Na Veletrhu práce a vzdělávání se setkáte se zástupci společností a institucí Plzeňského kraje i celé České republiky, kteří zde budou nabízet aktuální volné pracovní pozice.</span><br /><br /><span style=\"font-size: small;\">Účastí na Veletrhu práce a vzdělávání získáte:</span><br /><br /></p>\r\n<ul>\r\n<li><span style=\"font-size: small;\">lepší přehled o současném trhu pracovních příležitostí</span></li>\r\n<li><span style=\"font-size: small;\">osobní kontakt s personalisty renomovaných společností</span></li>\r\n<li><span style=\"font-size: small;\">nové znalosti a dovednosti účastí na doprovodném programu veletrhu</span></li>\r\n</ul>\r\n<p><br /><span style=\"font-size: small;\">Veletrh je otevřen všem studentům i absolventům středních škol, odborných škol, učilišť a Západočeské univerzity.</span><br /><br /><span style=\"font-size: small;\">Pro všechny je připraven bohatý doprovodný program.</span><br /><br /><span style=\"font-size: small;\">Přijďte připraveni. Přineste si svůj pracovní životopis, můžete ho osobně předat personalistům!</span><br /><br /><span style=\"font-size: small;\">Vstup je pro všechny návštěvníky zdarma.</span></p>\r\n<p><span style=\"font-size: small;\"></span>  </p>\r\n<p><span style=\"font-size: small;\"></span> </p>', '', '', 'jab1408', '2013-12-10 12:32:16');
INSERT INTO `paper` VALUES ('1330', '629', 'l14_04', 'Pro návštěvníky', null, '', null, 'jab1408', '2013-12-10 12:32:16');
