INSERT INTO `paper` VALUES ('1332', '631', 'l14_05', 'Doprovodný program', '<p><span style=\"font-size: small;\">Doprovodný program probíhá celý den.</span></p>\r\n<p><span style=\"font-size: small;\">Součástí programu jsou přednášky a řada dalších aktivit.</span></p>\r\n<p><span style=\"font-size: small;\">Účast na doprovodném programu zdarma!</span></p>\r\n<h2><span style=\"font-size: small;\">Přednášky</span></h2>\r\n<h3><span style=\"font-size: small;\">10:30 – 11:00 Jak se připravit na pracovní pohovor?</span></h3>\r\n<h3><span style=\"color: #000000; font-size: small;\">Vše, co byste měli vědět a na co si dát pozor...</span><span style=\"font-size: small;\"></span></h3>\r\n<h3><span style=\"font-size: small;\">11:15 – 11:45 Řekněte si o peníze na vzdělávání</span></h3>\r\n<p><span style=\"font-size: small;\">Víte, že na své vzdělávání můžete získat až 50000,- Kč od státu? Co pro to musíte udělat?</span></p>\r\n<h3><span style=\"font-size: small;\">12:00 – 12:30 Flexibilní formy práce jako řešení rodinné situace</span></h3>\r\n<p><span style=\"font-size: small;\">Zkrácené úvazky, teleworking a další formy práce z pohledu českých zákonů a praxe v podnicích</span></p>\r\n<h3><span style=\"font-size: small;\">12:45 – 13:15 Využití internetu pro personální marketing</span></h3>\r\n<p><span style=\"font-size: small;\">Jak pracovat s internetem, aby nám co nejlépe sloužil při hledání zaměstnání</span></p>\r\n<h3><span style=\"font-size: small;\">13:30 – 14:00 Jak získat zaměstnání v zahraničí?</span></h3>\r\n<p><span style=\"font-size: small;\">Evropské služby zaměstnanosti - EURES</span></p>\r\n<h3><span style=\"font-size: small;\">14:15 – 14:45 Těšíte se do penze?</span></h3>\r\n<p><span style=\"font-size: small;\">Jak se orientovat v současném světě financí, zejména v penzijní reformě</span></p>\r\n<h3><span style=\"font-size: small;\">15:00 – 15:30 Jak se připravit na pracovní pohovor?</span></h3>\r\n<p><span style=\"font-size: small;\">Vše, co byste měli vědět a na co si dát pozor...</span></p>\r\n<h3><span style=\"font-size: small;\">15:45 – 16:15 Řekněte si o peníze na své vzdělávání</span></h3>\r\n<p><span style=\"font-size: small;\">Víte, že na své vzdělávání můžete získat až 50000,- Kč od státu? Co pro to musíte udělat?</span></p>\r\n<h3><span style=\"font-size: small;\">16:30 – 17:30 Naučte se „prodávat“ sami sebe!</span></h3>\r\n<p><span style=\"font-size: small;\">Využijte marketingového přístupu při osobní prezentaci, u pracovního pohovoru nebo před šéfem...</span></p>\r\n<h2><span style=\"color: #888888;\"><strong><span style=\"font-size: small;\">(Změna programu vyhrazena)</span></strong></span></h2>\r\n<h2><span style=\"font-size: small;\">Další aktivity:</span></h2>\r\n<h3><span style=\"font-size: small;\">Individuální poradenství v oblasti vzdělávání a trhu práce</span></h3>\r\n<p><span style=\"font-size: small;\">Vezměte s sebou pracovní životopis a nechte si ho zkontrolovat odborníkem! Poraďte se, co je vhodné uvádět v životopisu! Co může a nemůže požadovat zaměstnavatel při pracovním pohovoru?</span></p>\r\n<h3><span style=\"font-size: small;\">Personální testování ZDARMA</span></h3>\r\n<p><span style=\"font-size: small;\">Odnesete si protokol s výsledky, který můžete přiložit k životopisu zasílanému zaměstnavateli</span></p>\r\n<h3><span style=\"font-size: small;\">Image poradna – Jak se upravit na pracovní pohovor</span><br /><br /><span style=\"font-size: small;\"><em>Změna programu vyhrazena</em></span></h3>\r\n<h2><span style=\"font-size: small;\">Prezentace společnosti formou přednášky:</span></h2>\r\n<h3><span style=\"font-size: small;\">11:00 – 11:30 <span style=\"color: #000000;\">SONY DADC</span></span></h3>\r\n<h3><span style=\"font-size: small;\">14:00 – 14:30 <span style=\"color: #000000;\">PERSONAL SERVICE</span></span></h3>\r\n<h3><span style=\"font-size: small;\">15:00 – 15:30 <span style=\"color: #000000;\">SONY DADC</span></span></h3>\r\n<h3><span style=\"font-size: small;\">16:00 – 16:30 <span style=\"color: #000000;\">S-COMP</span></span><span style=\"font-size: small;\"><span style=\"color: #000000;\"></span></span></h3>\r\n<h3> </h3>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:55:26');
