INSERT INTO `paper` VALUES ('1338', '637', 'l14_08', 'Mediální partneři', '<p> </p>\r\n<p> <img style=\"float: left;\" src=\"files/2764752.jpg\" alt=\"logo_plzen_2015\" /></p>\r\n<p>     Plzeň 2015, o.p.s.</p>\r\n<p> </p>\r\n<p> <img style=\"float: left;\" src=\"files/1787699.jpg\" alt=\"logo_region_plzen\" /></p>\r\n<p>     regionplzen.cz</p>\r\n<p> <br /><br /></p>\r\n<p> <img style=\"float: left;\" src=\"files/3377494.jpg\" alt=\"logo_cr\" /></p>\r\n<p>     Český rozhlas Plzeň</p>\r\n<p> </p>\r\n<p> </p>\r\n<p><img src=\"files/1832839.gif\" alt=\"logo_nejlepsi_adresa\" />      Plzeň - NEJLEPSI-ADRESA.CZ</p>\r\n<p> </p>\r\n<p> <img style=\"float: left;\" src=\"files/1657557.jpg\" alt=\"logo_zak\" /></p>\r\n<p>      TV ZAK   </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> <img style=\"float: left;\" src=\"files/1792903.jpg\" alt=\"logo_umo2\" /></p>\r\n<p> </p>\r\n<p>       ÚMO Plzeň 2</p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p>  <img style=\"float: left;\" src=\"files/3227005.jpg\" alt=\"logo_umo3\" /></p>\r\n<p>        ÚMO Plzeň 3</p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:55:34');
