INSERT INTO `paper` VALUES ('1350', '649', 'l14_11_01', 'BFZ - vzdělávací akademie', '<p><img style=\"float: right; margin-right: 50px;\" src=\"files/8669873.jpg\" alt=\"bfz\" /></p>\r\n<p> </p>\r\n<p style=\"text-align: justify;\"><br /><br /><strong><span style=\"font-size: large;\"><br />BFZ - VZDĚLÁVACÍ AKADEMIE</span></strong><br /><br /><br /><br /><br /><br />Společnost je součástí bavorského koncernu bbw Gruppe.</p>\r\n<p style=\"text-align: justify;\">Hlavní činností bfz - vzdělávací akademie je vzdělávání, přeškolování, kvalifikační kurzy, realizace projektů zaměřených na rozvoj lidských zdrojů, dočasné přidělování zaměstnanců a zprostředkování práce do Německa.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>BZF - Krajské středisko Plzeň<br />alej Svobody 56, 323 00 Plzeň</p>\r\n<p><a href=\"http://www.bfz.net\">www.bfz.net</a></p>\r\n<p> </p>\r\n<p>Jiří Kadlec<br />vedoucí bfz v Plzeňském kraji<br />tel.: +420 373 721 680<br />mobil: +420 777 686 201</p>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:55:52');
