INSERT INTO `paper` VALUES ('1353', '652', 'l14_11_02', 'Česká pojišťovna', '<p><br /> </p>\r\n<p> <img style=\"float: right; \" src=\"files/1916142.jpg\" alt=\"CP\" /><br /><span style=\"font-size: large;\"><strong>ČESKÁ POJIŠŤOVNA<br /></strong></span><span style=\"font-size: large;\"><strong><br /><br /></strong></span></p>\r\n<p style=\"text-align: left;\">Největší pojišťovna českého pojistného trhu s tradicí od roku 1827 - 3900 zaměstnanců a více než 3000 obchodních míst.</p>\r\n<p style=\"text-align: justify;\">Klientům a partnerům přinášíme jednoduchá, rychlá, férová a profesionální řešení, který vždy předčí jejich očekávání.</p>\r\n<p style=\"text-align: justify;\">Přijďte k nám, pomůžeme Vám s Vaší kariérou. <a href=\"http://www.pojistovna-kariera.cz\">www.pojistovna-kariera.cz</a></p>\r\n<p> </p>\r\n<h3>Kontakty:</h3>\r\n<p>Česká pojišťovna a.s.<br />Lucie Helusová<br />Slovanská alej 2442/24, 326 00 Plzeň</p>\r\n<p> </p>\r\n<p>mobil: +420 606 038 301<br />e-mail: <a href=\"mailto:lucie.helusova@ceskapojistovna.cz\">lucie.helusova@ceskapojistovna.cz</a><br /><a href=\"http://www.ceskapojistovna.cz\">www.ceskapojistovna.cz</a></p>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:55:56');
