INSERT INTO `paper` VALUES ('1365', '664', 'l14_11_06', 'Grafia', '<p><img style=\"float: right;\" src=\"files/3300732.jpeg\" alt=\"Grafia\" /></p>\r\n<p> </p>\r\n<p><span style=\"font-size: large;\"><strong><br />GRAFIA<br /><br /><br /><br /><br /></strong></span>Grafia, s.r.o. působí již 20 let na trhu v oblasti vzdělávání dospělých, marketingu, PR, reklamní a tiskové produkce, socio-ekonomických výzkumů, evropských projektů a v neposlední řadě v oblasti personálních služeb i outplacementových programů.</p>\r\n<p style=\"text-align: justify;\">Společnost nabízí řadu rozvojových programů pro zaměstnance podniků i individuální zájemce:</p>\r\n<p style=\"text-align: justify;\">► kurzy pro manažery i liniové pracovníky</p>\r\n<p style=\"text-align: justify;\">► akreditované rekvalifikační kurzy</p>\r\n<p style=\"text-align: justify;\">► kurzy pro specialisty</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Grafia spol. s r.o.<br />Budilova 4, 301 00 Plzeň<br />Sekce vzdělávání dospělých</p>\r\n<p><br />mobil: +420 377 227 701, <br />tel.: +420 378 771 222<br />e-mail: <a href=\"mailto:kurzy@grafia.cz\">kurzy@grafia.cz</a><br /><a href=\"http://www.grafia.cz\">www.grafia.cz</a></p>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:09');
