INSERT INTO `paper` VALUES ('1368', '667', 'l14_11_07', 'SŠ Horní Bříza', '<p><img style=\"float: right; margin-right: 50px;\" src=\"files/7589046.jpeg\" alt=\"soubor SOU Horní Bříza Logo200.jpeg\" /></p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\"><strong><span style=\"font-size: large;\"><br /><br /><br /><br />SŠ HORNÍ BŘÍZA</span></strong></p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\"> <br /><br /></p>\r\n<p style=\"text-align: justify;\"><br /><br />Vzdělávací nabídku tvoří maturitní obory s výtvarným a uměleckým zaměřením, dálkové maturitní nástavbové studium a tříleté obory Keramik, Obkladač, Kamnář, Elektrikář, Elektrotechnické a strojně montážní práce, Zámečník.</p>\r\n<p style=\"text-align: justify;\">Středisko celoživotního vzdělávání pořádá rekvalifikační i specializační kurzy v profesích Kamnář, Obkladač, Keramik, Montér strojů a zařízení a Dělník ve strojírenské výrobě.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Střední škola, Horní Bříza<br />U Klubu 302, 330 12 Horní Bříza</p>\r\n<p><br />Ing. Jaroslava Svitáková<br />tel.: +420 377 955 978</p>\r\n<p>e-mail: <a href=\"mailto:info@stredniskolahb.cz%20\">info@stredniskolahb.cz</a><br /><a href=\"http://www.stredniskolahb.cz\">www.stredniskolahb.cz</a><br /><a href=\"http://www.rekvalifikacehb.cz\">www.rekvalifikacehb.cz</a></p>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:12');
