INSERT INTO `paper` VALUES ('1371', '670', 'l14_11_08', 'Konplan', '<p> </p>\r\n<p> <img style=\"float: right; margin-right: 50px;\" src=\"files/8910053.jpg\" alt=\"soubor konplan_logo200jpeg.jpg\" /><br /><strong><span style=\"font-size: large;\">KONPLAN</span></strong><br /><br /><br /><br />Konplan realizuje specializované inženýrské služby šité na míru založené na odbornosti a důvěře. Staňte se experty v oboru konstrukce, projektování nebo programování a uplatněte svůj potenciál právě u nás. Nabízíme Vám prostor pro seberealizaci, profesní růst a atraktivní benefity.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Konplan s.r.o.<br />Poděbradova 2842/1, 301 00 Plzeň<br />Česká republika</p>\r\n<p> </p>\r\n<p>Mgr. Lena Vajdová</p>\r\n<p>tel.: +420 373 371 219<br />mobil: +420.602 266 239<br /><a href=\"http://www.konplan.cz\">www.konplan.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:14');
