INSERT INTO `paper` VALUES ('1374', '673', 'l14_11_09', 'Mlékárna Klatovy', '<p><img style=\"float: right; margin-right: 50px;\" src=\"files/6592889.jpeg\" alt=\"MK\" /> </p>\r\n<p> <br /><br /></p>\r\n<p> </p>\r\n<p><span style=\"font-size: large;\"><strong>MLÉKÁRNA KLATOVY</strong></span></p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p style=\"text-align: justify;\">Mlékárna Klatovy a.s. byla založena 30.3.1993. Je pokračovatelkou dlouholeté tradice mlékárenství v Klatovech sahající až do počátku 20 století.</p>\r\n<p style=\"text-align: justify;\">Od roku 2007 je součástí největšího mlékárenského uskupení na světě, francouzské skupiny Lactalis Group. V lednu 2013 zaměstnává 225 kmenových pracovníků a 35 dočasně přidělených agenturou práce.</p>\r\n<p style=\"text-align: justify;\">Výrobním programem jsou tvrdé, čerstvé a tavené sýry. Celkový roční objem výroby činí 12000 tun.</p>\r\n<h3> </h3>\r\n<p> </p>\r\n<h3>Kontakty:</h3>\r\n<p>Ing. Lucie Šimková</p>\r\n<p>Mlékárna Klatovy a.s.<br />Za Tratí 640, 339 01 Klatovy</p>\r\n<p> </p>\r\n<p>tel.: +420 376 700 298<br />mobil: +420 725 222 725<br />e-mail: <a href=\"mailto:lucie.simkova@lactalis.cz\">lucie.simkova@lactalis.cz</a></p>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:16');
INSERT INTO `paper` VALUES ('1375', '674', 'l14_11_09', 'Mlékárna Klatovy', null, '', null, 'administrator', '2013-11-19 10:56:16');
