INSERT INTO `paper` VALUES ('1377', '676', 'l14_11_10', 'Molins', '<p class=\"body\"> </p>\r\n<p class=\"body\"> </p>\r\n<p class=\"body\"><img style=\"float: right;\" src=\"files/1056663.jpeg\" alt=\"molins\" /></p>\r\n<p class=\"body\" style=\"text-align: justify;\"><span style=\"font-size: large;\"><strong><br />MOLINS</strong></span></p>\r\n<p class=\"body\" style=\"text-align: justify;\"> </p>\r\n<p class=\"body\" style=\"text-align: justify;\"> </p>\r\n<p class=\"body\" style=\"text-align: justify;\">MOLINS s.r.o. je dceřiná společnost britské společnosti Molins PLC, která je nadnárodní společností s dlouholetou tradicí v oblasti strojírenského průmyslu zabývající se především vývojem a výrobou speciálních strojů hlavně pro potravinářský a tabákový průmysl.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>MOLINS s.r.o.<br />Korandova 12, 301 00 Plzen<br />Czech Republic <br /><a href=\"http://www.molinstm.com\">www.molinstm.com</a></p>\r\n<p> </p>\r\n<p>Radka Lišková<br />Human Recources<br /><br />tel.: +420 378 080 313<br />mobil: +420 739 077 283 <br />fax: +420 378 080 211<br />e-mail: <a href=\"mailto:r.liskova@molins.cz\">r.liskova@molins.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:19');
