INSERT INTO `paper` VALUES ('1380', '679', 'l14_11_11', 'Mubea', '<p> </p>\r\n<p><img style=\"float: right; margin-right: 50px;\" src=\"files/1995097.jpeg\" alt=\"mubea\" /></p>\r\n<p> </p>\r\n<p><span style=\"font-size: large;\"><strong>MUBEA</strong></span></p>\r\n<p style=\"text-align: justify;\"><br /><br /><br /><br />Jsme firma Mubea a patříme mezi nejvýznamnější výrobce automobilových komponentů na celém světě.</p>\r\n<p style=\"text-align: justify;\">Dodáváme součástky předním automobilovým výrobcům, jako jsou například VW Group, Škoda Auto, Porsche, Audi, BMW, Renault, Ford a další.</p>\r\n<p style=\"text-align: justify;\">V současnosti zaměstnává koncern Mubea přibližně 7000 zaměstnanců po celém světě. Díky stabilitě společnosti nabízíme novým zaměstnancům perspektivu a jistotu v jejich profesním růstu.</p>\r\n<p style=\"text-align: justify;\">Dejte nám o sobě vědět a my Vám dáme příležitost.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Mubea, spol. s r.o.<br />Mubea Transmission Components s.r.o. <br />Motlová Bohuslava <br />personálního oddělení <br />Za dálnicí 510, 267 53 Žebrák <br />311 907 147<br /><a href=\"mailto:bohuslava.motlova@mubea.com\">bohuslava.motlova@mubea.com</a><br /><a href=\"http://www.mubea.com\">www.mubea.com</a> <br /> </p>\r\n<p>Mubea-HZP s.r.o<br />Mubea IT Spring Wire s.r.o.<br />Bc. Kateřina Krausová<br />personální oddělení<br />Dolní 100, 797 11 Prostějov<br />582 778 462<br /><a href=\"mailto:katerina.krausova@mubea.com\">katerina.krausova@mubea.com</a><br /><a href=\"http://www.mubea.com\">www.mubea.com</a></p>\r\n<p> </p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:22');
