INSERT INTO `paper` VALUES ('1383', '682', 'l14_11_12', 'OVB', '<p> <img style=\"float: right; margin-right: 50px;\" src=\"files/5144740.jpg\" alt=\"OVB\" /></p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: large;\"><strong><br /><br /><br />OVB<br /><br /><br /><br /><br /></strong></span></p>\r\n<p style=\"text-align: justify;\">Společnost OVB spolupracuje s ČNB, kde se snaží kontrolovat činnosti bank, pojišťoven a dalších institucí.</p>\r\n<p style=\"text-align: justify;\">Vizí je, zbavit klienta starostí ve světě financí tak, aby pro sebe ušetřil čas i peníze.</p>\r\n<p style=\"text-align: justify;\">OVB nabízí nové pracovní příležitosti a uplatnění ve finanční sféře a přináší možnost finanční svobody.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>OVB<br />Revoluční 92, 330 23 Nýřany</p>\r\n<p>Petr Hojda<br />mobil: +420 774 044 188<br />e-mail: <a href=\"mailto:petr.hojda@ovbmail.cz\">petr.hojda@ovbmail.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:25');
