INSERT INTO `paper` VALUES ('1386', '685', 'l14_11_13', 'Partner České Spořitelny', '<p> </p>\r\n<p><img style=\"float: right; margin-right: 50px;\" src=\"files/1668348.jpeg\" alt=\"soubor logo_PARTNER_CMYK_opt.jpeg\" /></p>\r\n<p> </p>\r\n<p><span style=\"font-size: large;\"><strong>PARTNER ČESKĚ SPOŘITELNY</strong></span></p>\r\n<p style=\"text-align: justify;\"><br /><br /><br /><br />Jsme součástí finanční skupiny České spořitelny, a.s.</p>\r\n<p style=\"text-align: justify;\">Naše nabídka zahrnuje širokou škálu bankovních produktů a služeb finanční skupiny České spořitelny a vybraných pojišťovacích produktů skupiny Vienna Insurance Group.</p>\r\n<p style=\"text-align: justify;\">Naším cílem je kvalitně uspokojit individuální finanční potřeby každého klienta.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Partner České spořitelny, a.s.<br />Poláčkova 1976/2, 140 21 Praha 4<br /><a href=\"http://www.partnercsas.cz\">www.partnercsas.cz</a></p>\r\n<p> </p>\r\n<p>Ing. Helena Šteinová<br />Denisovo nábřeží 6, Plzeň</p>\r\n<p>mobil: +420 608 877 557 <br />          +420 606 212 929</p>\r\n<p>e-mail: <a href=\"mailto:info@helenasteinova.cz\">info@helenasteinova.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:28');
