INSERT INTO `paper` VALUES ('1389', '688', 'l14_11_14', 'Personal service', '<p> </p>\r\n<p><img style=\"float: right; margin-right: 50px;\" src=\"files/1944746.jpeg\" alt=\"PS\" /><br /><br /><span style=\"font-size: large;\"><strong>PERSONAL SERVICE</strong></span><br /><br /></p>\r\n<p style=\"text-align: justify;\"><br /><br />Personal Service je nejmladší sekcí společnosti Grafia, s.r.o., která čerpá z dlouholeté zkušenosti společnosti prosperující již od roku 1993.</p>\r\n<p style=\"text-align: justify;\">Tým poradců Personal Service zajišťuje zprostředkování zaměstnání a krátkodobých brigád, individuální poradenství při hledání zaměstnání, osobnostní diagnostiku a další personální služby. Je stabilním partnerem pro podniky i zájemce o práci.</p>\r\n<p style=\"text-align: justify;\">Navštivte nás, vašim přáním porozumíme!</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Personal service <br />Přemyslova 1, Plzeň</p>\r\n<p><br />mobil: +420 775 878 801<br />e-mail: <a href=\"mailto:personalservice@grafia.cz\">personalservice@grafia.cz<br /></a><a href=\"http://www.personalservice.cz\">www.personalservice.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:31');
