INSERT INTO `paper` VALUES ('1392', '691', 'l14_11_15', 'Raiffeisen Stavební Spořitelna', '<p> <img style=\"float: right; margin-right: 50px;\" src=\"files/1605632.jpeg\" alt=\"RSTS\" /></p>\r\n<p> <span style=\"font-size: large;\"><strong>RAIFFEISEN Stavební Spořitelna</strong></span></p>\r\n<p><strong><span style=\"font-family: MyriadPro-BoldCond; font-size: x-large;\"><strong><span style=\"font-family: MyriadPro-BoldCond; font-size: x-large;\"></span></strong></span></strong></p>\r\n<p> </p>\r\n<p> </p>\r\n<p style=\"text-align: justify;\">Raiffeisen stavební spořitelna a.s. je součástí českého trhu od roku 1993. Od roku 1998 se Raiffeisen stavební spořitelna zaměřuje na bydlení a financování bydlení. Klientům díky snadné dostupnosti nabízí profesionální servis včetně poradenských služeb a hlavně širokou nabídku produktů pro realizaci jejich záměrů. Kromě půjčky na bydlení poskytuje i půjčky na bydlení, pojištění, včetně penzijního připojištění, a další finanční služby.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Raiffeisen stavební spořitelna a.s. <br />Koněvova 2747/99, 130 45 Praha 3</p>\r\n<p> </p>\r\n<p>Jakub Lisner<br />tel.: +420 271 032 617<br />mobil: +420 602 128 292</p>\r\n<p>e-mail: <a href=\"mailto:karieraOZ@rsts.cz\">karieraOZ@rsts.cz</a></p>\r\n<p><a href=\"http://www.rsts.cz\">www.rsts.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:34');
