INSERT INTO `paper` VALUES ('1395', '694', 'l14_11_16', 'Robert Bosch, spol. s r.o.', '<p> <img style=\"float: right; margin-right: 50px;\" src=\"files/1035059.jpeg\" alt=\"BOSCH\" /></p>\r\n<p><strong><span style=\"font-size: large;\">ROBERT BOSCH, spol. s r.o.</span><br /><br /></strong></p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\"><br />Společnost Robert Bosch je jedním z nejvýznamnějších výrobců a dodavatelů komponent pro automobilový průmysl. V minulých letech jsme v Českých Budějovicích kromě výroby vybudovali i moderní vývojové a zkušební centrum, které nám dovoluje pracovat na stále prestižnějších projektech.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Robert Bosch, spol. s r.o.<br />Roberta Bosche 2678 <br />370 04 České Budějovice</p>\r\n<p><br />Mgr. Lenka Kazdová<br />tel.: +420 380 404 765<br />fax: +420 380 404 213</p>\r\n<p>e-mail: <a href=\"mailto:lenka.kazdova@cz.bosch.com\">lenka.kazdova@cz.bosch.com</a></p>\r\n<p><a href=\"http://www.bosch.cz/kariera-cb\">www.bosch.cz/kariera-cb</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:38');
