INSERT INTO `paper` VALUES ('1398', '697', 'l14_11_17', 'Firma ROHDE & SCHWARZ závod Vimperk, s.r.o', '<p> <img style=\"float: right;\" src=\"files/2015822.jpeg\" alt=\"ROSCHW\" /></p>\r\n<p><span style=\"font-size: large;\"><strong><br /><br />ROHDE & SCHWARZ závod VIMPERK, s.r.o.</strong></span></p>\r\n<p><strong><span style=\"font-family: MyriadPro-BoldCond; font-size: x-large;\"><strong><span style=\"font-family: MyriadPro-BoldCond; font-size: x-large;\"></span></strong></span></strong> </p>\r\n<p style=\"text-align: justify;\"><br />Firma ROHDE & SCHWARZ závod Vimperk, s.r.o. je součástí světového koncernu Rohde & Schwarz, který je nadnárodní soukromou společností podnikající v oblastech elektronických testovacích a měřicích přístrojů, informačních technologií a radiokomunikací.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>ROHDE & SCHWARZ závod Vimperk, s.r.o<br />Špidrova 49, 385 01 Vimperk</p>\r\n<p> </p>\r\n<p>Ing. Tereza Kubásková<br />Personální oddělení</p>\r\n<p>e-mail: <a href=\"mailto:Tereza.Kubaskova@rohde-schwarz.com\">Tereza.Kubaskova@rohde-schwarz.com</a></p>\r\n<p>tel.: +420 388 452 313</p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:41');
