INSERT INTO `paper` VALUES ('1404', '703', 'l14_11_19', 'Sony DADC', '<p> <img style=\"float: right; margin-right: 50px;\" src=\"files/2100946.jpeg\" alt=\"SonyDADC\" /></p>\r\n<p><strong><span style=\"font-size: large;\">SONY DADC</span></strong></p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p style=\"text-align: justify;\">Sony DADC je dodavatelem technologií kompletních služeb a řešení pro optická média pro zábavní a vzdělávací průmysl, nově také pro tzv. Bio-Science.</p>\r\n<p>Společnost nabízí digitální řešení a výrobu CD, DVD, BD, UMD, servis od přípravy a tisku grafických částí po balení a distribuci hotových disků.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Sony DADC Czech Republic, s.r.o.<br />Dobranská 545, 332 09 Štěnovice <br />Czech Republic</p>\r\n<p> </p>\r\n<p>Julie Borecká<br />e-mail: <a href=\"mailto:julie.borecka@sonydadc.com\">julie.borecka@sonydadc.com<br /></a>tel.: +420377162423</p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:46');
