INSERT INTO `paper` VALUES ('1407', '706', 'l14_11_20', 'Sportovní a podnikatelská střední škola', '<p> </p>\r\n<p><img style=\"float: right; margin-right: 50px;\" src=\"files/3754756.jpeg\" alt=\"SPSPlzen\" /></p>\r\n<p> </p>\r\n<p> </p>\r\n<p> <br /><br /><br /><br /><br /></p>\r\n<p><strong><span style=\"font-size: large;\">Sportovní a podnikatelská střední škola</span></strong></p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p><br /> </p>\r\n<p style=\"text-align: justify;\">Naše škola je čtyřletá střední odborná, zakončená maturitou. Je určena pro sportovce i nesportovce. Vybrat si můžete z pěti odborností: firemní management, sportovní management, výpočetní technika, personalistika a psychologie, manažér zdravého životního stylu. Nabízíme dálkové studium pro vyučené a rekvalifikační kurzy.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Sportovní a podnikatelská střední škola s.r.o.<br />Sady 5. května 21, 301 12 Plzeň</p>\r\n<p> </p>\r\n<p>PhDr. Jan Sinkule<br />tel.: +420 377 225 933<br />e-mail: <a href=\"mailto:j.sinkule@sapss-plzen.cz\">j.sinkule@sapss-plzen.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:48');
INSERT INTO `paper` VALUES ('1408', '707', 'l14_11_20', 'Sportovní a podnikatelská střední škola', null, '', null, 'administrator', '2013-11-19 10:56:48');
