INSERT INTO `paper` VALUES ('1410', '709', 'l14_11_21', 'SŠ Oselce', '<p> <img style=\"float: right; margin-right: 50px;\" src=\"files/1452455.jpeg\" alt=\"Oselce\" /></p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\"><span style=\"font-size: large;\"><strong><br />SŠ OSELCE</strong></span></p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\"> </p>\r\n<p style=\"text-align: justify;\">Střední škola Oselce působí ve vzdělávání dětí i dospělých.</p>\r\n<p style=\"text-align: justify;\">V současnosti má pracoviště v Oselcích a Blovicích a specializuje se převážně na technické obory. Škola je zapojená do projektu UNIV2 financovaného z ESF a státního rozpočtu ČR.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Střední škola Oselce<br />Oselce 1, 335 01 Nepomuk</p>\r\n<p> </p>\r\n<p>Ing. Václav Bumbička<br />tel.: +420 371 595 168, +420 371 595 701</p>\r\n<p>e-mail: <a href=\"mailto:stskola.oselce@tiscali.cz\">stskola.oselce@tiscali.cz</a></p>\r\n<p><a href=\"http://www.stredniskolaoselce.cz\">www.stredniskolaoselce.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:52');
