INSERT INTO `paper` VALUES ('1413', '712', 'l14_11_22', 'ZČU - Ústav celoživotního vzdělání', '<p> <img style=\"float: right; \" src=\"files/4816118.jpeg\" alt=\"ZCU\" /></p>\r\n<p> </p>\r\n<p> </p>\r\n<p> </p>\r\n<p><span style=\"font-size: large;\"><strong>ZČU - ÚSTAV CELOŽIVOTNÍHO VZDĚLÁNÍ</strong></span></p>\r\n<p><br /> </p>\r\n<p> </p>\r\n<p style=\"text-align: justify;\">Ústav celoživotního vzdělávání vytváří nabídku vzdělávání pro zaměstnance, vedoucí pracovníky společností a veřejné správy.</p>\r\n<p style=\"text-align: justify;\">Oblastmi vzdělávání UCV jsou strojírenství, metalurgie, ekonomika podniku, logistika, průmyslový management, psychologie, jazyky, veřejná správa a E-learning.</p>\r\n<h3> </h3>\r\n<h3>Kontakty:</h3>\r\n<p>Západočeská univerzita v Plzni <br />Ústav celoživotního vzdělávání<br />Univerzitní 8, 306 14 Plzeň</p>\r\n<p><br /> </p>\r\n<p>tel.: +420 377 631 900<br />mobil: +420 725 874 755<br />e-mail: <a href=\"mailto:dezy@ucv.zcu.cz\">dezy@ucv.zcu.cz</a><br /><a href=\"http://www.ucv.zcu.cz\">www.ucv.zcu.cz</a></p>\r\n<p> </p>', '', '', 'administrator', '2013-11-19 10:56:54');
