INSERT INTO `paper` VALUES ('1422', '721', 'l15', 'ROK 2022', '<div style=\"text-align: center;\">\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><strong>10. ročník proběh<span style=\"font-size: small;\"><strong>l <span style=\"color: #e20019; font-size: small;\"><strong>12. 4. 2022</strong></span></strong></span> v <a title=\"Úslavská 75, Plzeň\" href=\"https://www.google.com/maps/place/TJ+Lokomotiva+Plze%C5%88/@49.7389514,13.3943343,17z/data=!3m1!4b1!4m5!3m4!1s0x470af1d90057fd93:0x72223eeb580172f7!8m2!3d49.7389562!4d13.3965154\" target=\"_blank\">TJ Lokomotiva Plzeň</a>, Úslavská 75 <span style=\"color: #e20019; font-size: small;\"><strong></strong></span><br /></strong>záštitu nad akcí převzal senátor Ing. Lumír Aschenbrenner</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #e20019; font-size: small;\"><span class=\"d2edcug0 hpfvmrgz qv66sw1b c1et5uql lr9zc1uh a8c37x1j fe6kdd0r mau55g9w c8b282yb keod5gw0 nxhoafnm aigsh9s9 d3f4x2em iv3no6db jq4qci2q a3bd9o3v b1v8xokw oo9gr5id hzawbc8m\" style=\"color: #000000;\"> Přijít se vyplatilo, i když jste práci zrovna nehledali. </span></span><span style=\"font-size: small;\">Na veletrhu byly </span><a style=\"font-size: small;\" title=\"program\" href=\"../index.php?list=l15_01&language=lan1&lay=\" target=\"_blank\">poradny, přednášky</a><span style=\"font-size: small;\"> a desítky </span><a style=\"font-size: small;\" title=\"firmy\" href=\"index.php?list=l15_04\" target=\"_blank\">vystavovatelů</a><span style=\"font-size: small;\"> se stovkou </span><a style=\"font-size: small;\" title=\"pozice\" href=\"index.php?list=l15_06\" target=\"_blank\">pracovních míst</a><span style=\"font-size: small;\"> od dělnických po specializované a manažerské pozice!</span></p>\r\n<p style=\"text-align: center;\"><span style=\"color: #e20019;\"><span style=\"font-size: medium;\"><span style=\"color: #000000; vertical-align: middle; font-size: small;\">Sledujte nás na sociálních sítích: </span></span></span><a title=\"Veletrh práce a vzdělávání Plzeň - Klíč k příležitostem\" href=\"https://www.facebook.com/veletrhprace\" target=\"_blank\"><img style=\"vertical-align: top; margin-top: -1px;\" title=\"facebook\" src=\"files/1153903.png\" alt=\"facebook\" height=\"33\" /> </a><a href=\"https://www.instagram.com/veletrhprace/\" target=\"_blank\"><img style=\"vertical-align: top;\" title=\"instagram\" src=\"files/3564869.jpg\" alt=\"ikona-instagram\" height=\"34\" /></a><a href=\"https://cz.linkedin.com/company/grafia-s.r.o.\" target=\"_blank\"><img style=\"margin-left: 7px; margin-top: 1px; vertical-align: top;\" title=\"linkedin\" src=\"files/4158925.png\" alt=\"linkedin\" height=\"31\" /></a></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><a href=\"https://veletrhprace.rajce.idnes.cz/Veletrh_prace_a_vzdelavani_2022/\" target=\"_blank\">Fotografie</a> přidáváme postupně <a href=\"https://veletrhprace.rajce.idnes.cz/Veletrh_prace_a_vzdelavani_2022/\" target=\"_blank\">ZDE</a>.</span></p>\r\n<p style=\"text-align: center;\"> </p>\r\n<p style=\"text-align: center; clear: both;\"> <img src=\"files/1476462.jpg\" alt=\"soubor fotyk z veletrhu kolaz na web.jpg\" width=\"600\" /></p>\r\n<hr />\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong><span style=\"color: #000000;\"><br /></span></strong></span></span></p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small;\"><span style=\"color: #e20019;\"><strong><span style=\"color: #000000;\">Předchozí ročníky naleznete v levém menu.</span></strong></span></span></p>\r\n<p> </p>\r\n</div>\r\n<p style=\"text-align: center;\"><span style=\"font-size: small; color: #333333;\"><span style=\"font-size: xx-small;\"> --%VLOZVIDEOFLV_200127 Studio Z_Grafia_Veletrh_prace_2020%-- </span> <br /> </span></p>', '', '', 'administrator', '2022-11-09 14:24:13');
