INSERT INTO `paper` VALUES ('1533', '832', 'l15_06', 'Nabízená pracovní místa', '<p><span style=\"font-size: medium;\"><strong>Každý rok je nabídka pracovních míst jiná a vždy pestrá.<br />Seznam nabízených pracovních míst pro rok 2022:<br /></strong></span></p>\r\n<div> </div>\r\n<div style=\"display: flex; flex-direction: row; font-size: small;\">\r\n<div>\r\n<div>Administrativni pracovník (m, ž),</div>\r\n<div>Asistent výroby v potravinářském průmyslu (m, ž),</div>\r\n<div>Operátor výroby (m, ž),</div>\r\n<div>Seřizovač strojů a výrobních línií (m, ž),</div>\r\n<div>Obsluha výrobních línií (m, ž),</div>\r\n<div>Skladník (m, ž),</div>\r\n<div>Řidič vysokozdvižného vozíku (m, ž),</div>\r\n<div>Svářeč (m, ž),</div>\r\n<div>Obsluha CNC strojů (m, ž),</div>\r\n<div>Programátor CNC strojů (m, ž),</div>\r\n<div>Lakýrník (m, ž),</div>\r\n<div>Kontrola kvality,</div>\r\n<div>Operátor výroby,</div>\r\n<div>Elektroúdržbář,</div>\r\n<div>Zástupce mistra v oddělení kvality,</div>\r\n<div>Zástupce mistra v oddělení výroby,</div>\r\n<div>IT inženýr v oddělení údržby,</div>\r\n<div>Vývojový inženýr,</div>\r\n<div>Design inženýr,</div>\r\n<div>Testovací inženýr,</div>\r\n<div>Tester,</div>\r\n<div>Inženýr pro správu testovacích laboratoří,</div>\r\n<div>Náborář,</div>\r\n<div>Výrobní inženýr pro oblast výrobních linek,</div>\r\n<div>Výrobní inženýr pro výrobní zařízení,</div>\r\n<div>Výrobní inženýr pro robotizaci a strojové vidění,</div>\r\n<div>Lisař,</div>\r\n<div>Přípraváře/ku, kalkulanta/ku,</div>\r\n<div>Asistenta/ku vedoucího projektu,</div>\r\n<div>Mistry stavby,</div>\r\n<div>Stavbyvedoucí,</div>\r\n<div>Tesaře,</div>\r\n<div>Zedníky,</div>\r\n<div>Strojníky,</div>\r\n<div>Stavební dělníky,</div>\r\n<div>Řidiče na částečný úvazek,</div>\r\n<div>Operátory výroby,</div>\r\n<div>Interní logistiky,</div>\r\n<div>Skladníky,</div>\r\n<div>Údržbáře elektro,</div>\r\n<div>Mechatroniky,</div>\r\n<div>Výrobní inženýry,</div>\r\n<div>Průmyslové inženýry,</div>\r\n<div>Průmyslové IT inženýry,</div>\r\n<div>Průmyslové IT,</div>\r\n<div>Inženýry kvality,</div>\r\n<div>Kontrolory kvality,</div>\r\n<div>\r\n<div>Obsluha/seřizovač CNC,</div>\r\n<div>Obsluha lisu a laseru,</div>\r\n<div>Programátor SW,</div>\r\n<div>Svářeč,</div>\r\n<div>Disponent,</div>\r\n<div>Řidič VZV,</div>\r\n<div>\r\n<div>Operátor výroby,</div>\r\n<div>Seřizovač,</div>\r\n<div>Údržbár,</div>\r\n<div>Zásobovač,</div>\r\n</div>\r\n</div>\r\n<div>Machr na kvalitu - Dýšina,</div>\r\n<div>Machr na výrobu plechovek, obsluha strojů - Dýšina,</div>\r\n<div>Provozní technici výrobních zařízení - Dýšina a Plzeň,</div>\r\n<div>Směnový mistr / výroba plechovek - Dýšina a Plzeň,</div>\r\n<div>IT Site Support Technician - Plzeň,</div>\r\n<div>Elektroinženýr pro nový projekt - Plzeň,</div>\r\n<div>Specialista v oboru chemie - Plzeň,</div>\r\n<div>Technik servisního centra - Vývojové a servisní středisko,</div>\r\n<div>Quality manager - Plzeň,</div>\r\n<div>Denní elektrikář - Plzeň,</div>\r\n<div>Tlumočník / překladatel technických školení - Dýšina,</div>\r\n<div>Production Manager - Plzeň,</div>\r\n<div>Operátor montáže – dvousměnný provoz,</div>\r\n<div>Svářeč  - třísměnný provoz,</div>\r\n<div>Lakýrník – třísměnný provoz,</div>\r\n<div>Mistr výroby – dvousměnný provoz,</div>\r\n<div>Údržbář – dvousměnný provoz, případně třísměnný provoz,</div>\r\n<div>Technolog montáže,</div>\r\n<div>Konstruktér / Vývojář,</div>\r\n<div>Mistr montáží NN/VN (Karlovy Vary)</div>\r\n<div>Mistr montáží NN/VN (Písek)</div>\r\n<div>Montér NN/VN (Karlovy Vary)</div>\r\n<div>Montér NN/VN (Písek)</div>\r\n<div>Montér NN/VN (Domažlice)</div>\r\n<div>Montér NN/VN (Česká Lípa)</div>\r\n<div>Montér NN/VN (Teplice)</div>\r\n<div>Montér NN/VN (Jirkov)</div>\r\n<div>Montér NN/VN (Litoměřice)</div>\r\n<div>Montér pro rozvodny (Brno – turnusy)</div>\r\n<div>Technik přípravy a řízení staveb VVN (Plzeň)</div>\r\n<div>Technik plánování a přípravy staveb (Brno)</div>\r\n<div>Projektant VVN/VN (Praha)</div>\r\n<div>Autorizovaný technik pro technologické zařízení staveb (Plzeň – turnusy)</div>\r\n<div>Projektant/ka NN/VN (České Budějovice)</div>\r\n<div>Projektant/ka NN/VN (Česká Lípa)</div>\r\n<div>Vedoucí projektant/ka NN/VN (Plzeň)<br />Projektant/ka NN/VN (Plzeň), vhodné pro absolventy</div>\r\n<div> </div>\r\n</div>\r\n<div> </div>\r\n<div> </div>\r\n<div>\r\n<div>Svářeč,</div>\r\n<div>Softwarový vývojář se zaměřením na webový frontend,</div>\r\n<div>Softwarový vývojář se zaměřením na vývoj aplikací,</div>\r\n<div>Referent prodeje/technik,</div>\r\n<div>Referent/ka ÚŘJH,</div>\r\n<div>Mistr/ová výrobního provozu,</div>\r\n<div>Expedient hotových výrobků,</div>\r\n<div>Zámečník – údržba výroby,</div>\r\n<div>Elektrikář,</div>\r\n<div>Předák výrobního provozu,</div>\r\n<div>Dělník v potravinářské výrobě,</div>\r\n<div>Ošetřovatel/ka – výkrm kuřat – HBL farma Horšov,</div>\r\n<div>Vedoucí provozu HBL farmy,</div>\r\n<div>Montér,</div>\r\n<div>Konstruktér,</div>\r\n<div>Technolog,</div>\r\n<div>Kvalitář</div>\r\n<div>Třídič/ka,</div>\r\n<div>Strojník,</div>\r\n<div>Manipulant,</div>\r\n<div>Seřizovač kontrolních automatů,</div>\r\n<div>Technolog,</div>\r\n<div>Obráběč/-ka kovů,</div>\r\n<div>Zámečník/zámečnice,</div>\r\n<div>Operátor v galvanovně,</div>\r\n<div>Obráběč kovů,</div>\r\n<div>Zámečník,</div>\r\n<div>Mechanik strojů a zařízení,</div>\r\n<div>Mechanik seřizovač,</div>\r\n<div>Instalatér,</div>\r\n<div>Elektrikář,</div>\r\n<div>Automechanik,</div>\r\n<div>Policista/tka pro obvodní oddělení,</div>\r\n<div>Policista/tka pro dopravní policii,</div>\r\n<div>Policista/tka pro odbor cizinecké policie,</div>\r\n<div>Policista/tka pro oddělení hlídkové služby,</div>\r\n<div>Vedoucí/manager strategického nákupu</div>\r\n<div>Strojní technik,</div>\r\n<div>Konstruktér,</div>\r\n<div>Celní deklarant – Plzeň,</div>\r\n<div>Inženýr technické laboratoře,</div>\r\n<div>Specialista IMS (integrovaného systému kvaliy),</div>\r\n<div>Specialista zpracování dat,</div>\r\n<div>Inženýr zákaznické kvality,</div>\r\n<div>Technik laboratoře / specialista elektro,</div>\r\n<div>Technolog mikrovstřikování plastů,</div>\r\n<div>Technický nákupčí,</div>\r\n<div>Seřizovač / elektromechanik,</div>\r\n<div>Seřizovač střihacích strojů (střihač),</div>\r\n<div>Seřizovač automatických linek / mechatronik,</div>\r\n<div>Seřizovač vstřikolisů,</div>\r\n<div>Elektrikář,</div>\r\n<div>Mechanik montáže,</div>\r\n<div>Skladník technického materiálu,</div>\r\n<div>Pracovník příjmu a expedice zboží – Plzeň,</div>\r\n<div>Skladník/ -ice,</div>\r\n<div>Svářecí technolog,</div>\r\n<div>Logistik-manipulant,</div>\r\n<div>Koordinátor kooperací,</div>\r\n<div>Parťák mistra logistiky,</div>\r\n<div>Obsluha ohraňovacího lisu,</div>\r\n<div>Parťák mistra svařovny,</div>\r\n<div>Svářeč s oprávněním CO<sub>2,</sub></div>\r\n<div>Pekař specialista,</div>\r\n<div>Elektromechanik,</div>\r\n<div>Svářeč (včetně rekvalifikace),</div>\r\n<div>Skladník,</div>\r\n<div>Kontrolor kvality,</div>\r\n<div>Pracovník povrchové úpravy karoserie (AF),</div>\r\n<div>Údržbář elektro,</div>\r\n<div>Kontrolor dodavatelské kvality s NJ,</div>\r\n<div>Specialista logistiky,</div>\r\n<div>Operátory / operátorky výroby,</div>\r\n<div>Seřizovače linek,</div>\r\n<div>Mechatroniky,</div>\r\n<div>Nástrojář,</div>\r\n<div>CNC soustružník/mechanik obrábění kovů</div>\r\n<div>Seřizovač/údržba CNC strojů,</div>\r\n<div>Operátor v elektrovýrobě,</div>\r\n<div>Technik/údržbář/seřizovač v elektrovýrobě,</div>\r\n<div>Technik industry engineering,</div>\r\n<div>Technik oddělení testovací techniky (kontrukce/hardware),</div>\r\n<div>Programátor aplikací (C#, VB.net, SQL)</div>\r\n<div> </div>\r\n</div>\r\n</div>\r\n<hr />\r\n<div> </div>\r\n<div> </div>', '', '', 'administrator', '2022-11-09 14:39:57');
