INSERT INTO `paper` VALUES ('1539', '838', 'l16_01', 'Dokumenty ke stažení', '<p> </p>\r\n<p>Zde jsou k dispozici dokumenty pro vystavovatele a zájemce o účast na Veletrhu práce a vzdělávání 2016:</p>\r\n<p> </p>\r\n<p><a href=\"index.php?list=download&file=1794629.pdf\" target=\"_blank\">Veletrh_práce a vzdělání 2016_pozvánka</a></p>\r\n<p><a href=\"index.php?list=download&file=5794676.xls\" target=\"_blank\">Vystavovatel - Registrační formulář - Veletrh práce a vzdělávání Plzeň 2016</a></p>\r\n<p><a href=\"index.php?list=download&file=1302779.xls\" target=\"_blank\">Vystavovatel - Specifikace služeb - Veletrh práce a vzdělávání Plzeň 2016</a></p>\r\n<p><a href=\"index.php?list=download&file=1457548.xls\" target=\"_blank\">Vystavovatel - Stanovení termínů - Veletrh práce a vzdělávání Plzeň 2016</a></p>\r\n<p><a href=\"index.php?list=download&file=5583133.doc\" target=\"_blank\"> Smlouva vystavovatel - vzor</a></p>\r\n<p><a href=\"index.php?list=download&file=2053548.doc\" target=\"_blank\">Všeobecné podmínky ke smlouvě</a></p>\r\n<p> </p>', '', '', 'administrator', '2016-06-24 09:31:40');
INSERT INTO `paper` VALUES ('1540', '839', 'l16_01', 'Dokumenty ke stažení', null, '', null, 'administrator', '2016-06-24 09:31:40');
