INSERT INTO `paper` VALUES ('1545', '844', 'l19', 'Kontakty', '<h1><span style=\"color: #000000;\">Kontaktní e-mail pro vystavovatele:</span></h1>\r\n<p><span style=\"color: #000000;\"><strong><a href=\"mailto:obchod@grafia.cz\"><span style=\"color: #000000;\">obchod@grafia.cz</span></a></strong> </span></p>\r\n<h1><span style=\"color: #000000;\">Kontaktní e-mail pro návštěvníky:</span></h1>\r\n<p><span style=\"color: #000000;\"><strong><a href=\"mailto:info@grafia.cz\"><span style=\"color: #000000;\">info@grafia.cz</span></a></strong></span></p>\r\n<h1><span style=\"color: #000000;\">Organizace a propagace:</span></h1>\r\n<p><span style=\"color: #000000;\">Grafia, s.r.o.</span></p>\r\n<p><span style=\"color: #000000;\">Budilova 4, 301 21 Plzeň</span></p>\r\n<p><span style=\"color: #000000;\"><a href=\"http://www.grafia.cz\"><span style=\"color: #000000;\">www.grafia.cz</span></a></span></p>\r\n<p> </p>\r\n<p> </p>', '', '', 'jab1408', '2023-12-21 02:30:06');
