INSERT INTO `paper` VALUES ('1563', '862', 'l24_05', 'Seznam vystavovatelů', '<p><span style=\"font-size: medium;\"><strong><span style=\"font-family: arial,helvetica,sans-serif;\">V roce 2016 se veletrhu zúčastní níže uvedení vystavovatelé</span></strong></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><br /></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><a href=\"http://www.amboseli.cz/\" target=\"_blank\">AMBOSELI s.r.o.</a><br /></span></p>\r\n<p><a href=\"http://www.borgers-group.com/index.php\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Borgers CS spol. s.r.o.</span></a></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><a href=\"https://www.ceskapojistovna.cz/\" target=\"_blank\">Česká pojišťovna a.s.</a><br /></span></p>\r\n<p><a href=\"http://www.daikinczech.cz/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Daikin Industries Czech Republic s.r.o.</span></a></p>\r\n<p><a href=\"http://www.dzklatovy.cz/cesky/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Drůbežářský závod Klatovy a.s.</span></a></p>\r\n<p><a href=\"http://www.faiveleytransport.com/energy-comfort/faiveley-transport-lekov\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">FAIVELEY TRANSPORT LEKOV a.s.</span></a></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><a href=\"https://www.gemoney.cz/\" target=\"_blank\">GE Money Bank, a. s. </a><br /></span></p>\r\n<p><a href=\"http://www.hofmann-personal.cz/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">HOFMANN WIZARD s.r.o.</span></a></p>\r\n<p><a href=\"http://www.in-tech.de/cz/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">in-tech Automotive Engineering s.r.o.</span></a></p>\r\n<p><a href=\"http://www.jtekt.cz/cs/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"> JTEKT Automotive Czech Plzen s.r.o.</span></a></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><a href=\"http://www.kermi.cz/\" target=\"_blank\">Kermi s.r.o.</a></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><a href=\"http://www.kb.cz/\" target=\"_blank\">Komerční banka, a.s.</a><br /></span></p>\r\n<p><a href=\"http://www.kostal.cz/html/showdoc.dodocid=6459.html\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">KOSTAL CR, spol. s.r.o.</span></a></p>\r\n<p><a href=\"http://www.kcvjs.cz/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Krajské centrum vzdělávání a Jazyková škola s právem státní jazykové zkoušky</span></a></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><a title=\"KS EUROPE\" href=\"http://www.ks-europe.com/cs/\" target=\"_blank\">KS - EUROPE</a><span style=\"color: #ff0000;\">, s.r.o.</span></span></p>\r\n<p><a href=\"http://www.f-plast.com/cz/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">KUNSTSTOFF-FRÖHLICH Czech Plast s.r.o.</span></a></p>\r\n<p><a href=\"http://www.lear.com/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Lear Corporation Czech Republic s.r.o.</span></a></p>\r\n<p><span style=\"font-size: small; font-family: arial,helvetica,sans-serif;\"><a href=\"http://www.makro.cz/\" target=\"_blank\">MAKRO Cash & Carry ČR s.r.o.</a><br /></span></p>\r\n<p><a href=\"http://www.md-elektronik.de/cs.html\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">MD ELEKTRONIK spol. s.r.o.</span></a></p>\r\n<p><a href=\"http://www.mubea.com/cz/home/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Mubea, spol. s.r.o.</span></a></p>\r\n<p><a href=\"http://www.o2.cz/osobni/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">O2 Czech Republic a.s.</span></a></p>\r\n<p><a href=\"http://www.randstad.cz/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Randstad s.r.o.</span></a></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><a href=\"http://www.shapecorp.cz/\" target=\"_blank\">Shape Corp. Czech Republic, s.r.o.</a></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><a href=\"http://www.sonydadc.com/en/\" target=\"_blank\">Sony DADC Czech Republic, s.r.o.</a><br /></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small; color: #000000;\"><a href=\"http://www.steelcase.com/countries/czech-republic/\" target=\"_blank\">Steelcase Czech Republic s.r.o.</a><br /></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small; color: #000000;\"><a href=\"http://www.styl-plzen.cz/\" target=\"_blank\">STYL PLZEŇ, výrobní družstvo</a><br /></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small; color: #000000;\"><a href=\"http://www.swa.cz/cz/swa/\" target=\"_blank\">SWA, s.r.o.</a><br /></span></p>\r\n<p><a href=\"http://www.ubk.cz/cz/\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">UBK s.r.o.</span></a></p>\r\n<p><a href=\"https://portal.mpsv.cz/eures\" target=\"_blank\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\">Úřad práce ČR - EURES</span></span></a></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-si