INSERT INTO `paper` VALUES ('1776', '1075', 'l27_05', 'Doprovodný program', '<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>Doprovodný program probíhá celý den.</strong></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>Součástí programu jsou přednášky a řada dalších aktivit.</strong></span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif;\"><span style=\"font-size: small;\"><strong>Účast na doprovodném programu je zdarma!</strong><br /></span> </span></p>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong><span style=\"color: #e42d24;\">Přednášková místnost č. 1</span></strong></span></p>\r\n<h2><span style=\"font-family: arial,helvetica,sans-serif;\"> </span><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>10:30 – 11:00</strong> <strong>Jak se připravit na pracovní pohovor?</strong></span><br /><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong> </strong>Vše, co byste měli vědět a na co si dát pozor...</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>11:15 – 11:45</strong> <strong>Získejte až 50.000 Kč od státu na své vzdělávání! </strong>Co pro to musíte udělat?</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>12:00 – 12:30</strong> <strong>SONY DADC </strong>prezentace společnosti, nabízené pracovní pozice</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>12:45 – 13:15</strong> <strong>Využití internetu pro personální marketing </strong>Jak pracovat s internetem, aby nám co nejlépe sloužil při hledání zaměstnání?</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>13:30 – 14:00 Jak získat zaměstnání v zahraničí?</strong></span><br /><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"> Evropské služby zaměstnanosti – Eures</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>14:15 – 14:45</strong> <strong>Získejte až 50.000 Kč od státu na své vzdělávání! </strong>Co pro to musíte udělat?</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>15:00 – 15:30</strong> <strong>Těšíte se do penze?</strong></span><br /><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"> Jak se orientovat v současném světě financí, zejména v penzijní reformě</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>15:45 – 16:15</strong> <strong>Jak se připravit na pracovní pohovor? </strong>Vše, co byste měli vědět a na co si dát pozor...</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>16:30 – 17:00</strong> <strong>Naučte se prodávat <br /> sami sebe! </strong>Ochutnávka kurzu marketingové myšlení pro osobní prezentaci, u pracovního pohovoru nebo před šéfem...</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>17:15 – 18:00  Máte šanci v zahraniční firmě? Ukázky videí a testů z kurzů OPEN DOOR</strong> (profesní AJ a NJ)</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\">  </span></h2>\r\n<p><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong><span style=\"color: #e42d24;\">Přednášková místnost č. 2</span></strong></span></p>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>11:15 – 11:45 Jak si vybrat kvalitní kurz? </strong>Zorientujte se v široké nabídce kurzů </span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>12:00 – 12:30</strong> <strong>Je „padesátka“ překážkou v nalezení zaměstnání?</strong> Pomůže Vám projekt Help 50+ </span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>13:00 – 14:45</strong> <strong>Domluvíte se ve své profesi? Otestujte své znalosti z profesní NJ a AJ <br /> </strong>(test s doporučením k dalšímu studiu)</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>15:00 – 15:45  Máte šanci v zahraniční firmě? Ukázky videí a testů z kurzů OPEN DOOR</strong> (profesní AJ a NJ) </span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>16:00 – 16:45</strong> <strong>Domluvíte se ve své profesi? Otestujte své znalosti z profesní NJ a AJ <br /> </strong>(test s doporučením k dalšímu studiu)</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>17:00 – 17:30  Feng shui doma i na pracovišti: </strong>nechte energii pracovat pro vás! (ochutnávka kurzu)</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong><br /></strong></span></h2>\r\n<h2><span style=\"font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>Další aktivity:</strong></span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>• Individuální poradenství v oblasti vzdělávání a trhu práce </strong>Vezměte s sebou pracovní životopis a nechte si ho zkontrolovat odborníkem! (balkon)</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>• Image poradna</strong> zaměřená na přípravu na pracovní pohovor (balkon)</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>• Personální testování ZDARMA </strong></span><br /><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong> </strong>Odneste si protokol s výsledky, který můžete přiložit k životopisu zasílanému zaměstnavateli (balkon)</span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>• Slosování o ceny každou hodinu</strong></span></h2>\r\n<h2><span style=\"color: #000000; font-family: arial,helvetica,sans-serif; font-size: small;\"><strong>• Vyhlášení cen pro podniky přátelské rodině </strong>(13,00 hod, jeviště hlavní sál)</span></h2>', '', '', 'jab1408', '2015-09-23 12:58:29');
INSERT INTO `paper` VALUES ('1777', '1076', 'l27_05', 'Doprovodný program', null, '', null, 'jab1408', '2015-09-23 12:58:29');
