INSERT INTO `paper` VALUES ('1779', '1078', 'l27_06', 'Mediální ohlasy', '<p><strong><br /><span style=\"font-size: medium;\"><span style=\"color: #000000;\">Veletrh Klíč k příležitostem 2014<br /><br /></span><span style=\"color: #000000;\"><a href=\"files/1925938.pdf\" target=\"_blank\"><span style=\"text-decoration: underline;\">Všechny články o veletrhu Klíč k příležitostem 2014 v pdf</span></a></span></span></strong></p>\r\n<p><span style=\"font-size: small;\"><strong>Andromedia.cz</strong></span><br /><span style=\"font-size: small;\">28. 1. 2014</span><br /><span style=\"font-size: small;\"><span style=\"text-decoration: underline;\"><a href=\"http://www.andromedia.cz/veletrh-prace-vzdelavani-klic-k-prilezitostem-v-plzni\">http://www.andromedia.cz/veletrh-prace-vzdelavani-klic-k-prilezitostem-v-plzni</a></span> </span></p>\r\n<p><span style=\"font-size: small;\"><strong>Personalistika-vzdelavani.cz</strong></span><br /><span style=\"font-size: small;\">28. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.personalistika-vzdelavani.cz/a-357/ohlednuti-za-veletrhem-prace-a-vzdelavani-klic-k-prilezitostem%20%20Novinky.cz\">http://www.personalistika-vzdelavani.cz/a-357/ohlednuti-za-veletrhem-prace-a-vzdelavani-klic-k-prilezitostem</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Novinky.cz</strong></span><br /><span style=\"font-size: small;\">27. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.novinky.cz/kariera/325715-do-pekla-prisly-hledat-praci-tisice-lidi.html\">http://www.novinky.cz/kariera/325715-do-pekla-prisly-hledat-praci-tisice-lidi.html</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Plzen.cz</strong></span><br /><span style=\"font-size: small;\">24. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.plzen.cz/zpravy/clanky/Firmy-z-Plzenska-uz-nechteji-vetsinove-montazni-delniky-17206\">http://www.plzen.cz/zpravy/clanky/Firmy-z-Plzenska-uz-nechteji-vetsinove-montazni-delniky-17206</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Umo3.plzen.eu</strong></span><br /><span style=\"font-size: small;\">24. 1 . 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://umo3.plzen.eu/aktuality/veletrh-prace-a-vzdelavani-navstivily-tisice-lidi.aspx\">http://umo3.plzen.eu/aktuality/veletrh-prace-a-vzdelavani-navstivily-tisice-lidi.aspx</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Plzeňský deník</strong></span><br /><span style=\"font-size: small;\">24. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://plzensky.denik.cz/zpravy_region/klic-byl-setkanim-se-zamestnavateli-20140123.html\">http://plzensky.denik.cz/zpravy_region/klic-byl-setkanim-se-zamestnavateli-20140123.html</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>QAP.cz</strong></span><br /><span style=\"font-size: small;\">23. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.qap.cz/zpravy/object/plzenske-peklo-praskalo-ve-svech-nabizela-se-prace-a-vzdelavani-mame-fotky-55548/article.htm\">http://www.qap.cz/zpravy/object/plzenske-peklo-praskalo-ve-svech-nabizela-se-prace-a-vzdelavani-mame-fotky-55548/article.htm</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Blesk.cz</strong></span><br /><span style=\"font-size: small;\">23. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.blesk.cz/clanek/live-zpravy/229934/firmy-z-plzenska-uz-nechteji-vetsinove-montazni-delniky.html\">http://www.blesk.cz/clanek/live-zpravy/229934/firmy-z-plzenska-uz-nechteji-vetsinove-montazni-delniky.html</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Novinky.cz</strong></span><br /><span style=\"font-size: small;\">23. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.novinky.cz/vase-zpravy/plzensky-kraj/plzen-mesto/4164-22349-plzen-hostila-veletrh-prace-a-vzdelavani-klic-k-prilezitostem.html\">http://www.novinky.cz/vase-zpravy/plzensky-kraj/plzen-mesto/4164-22349-plzen-hostila-veletrh-prace-a-vzdelavani-klic-k-prilezitostem.html</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Český rozhlas Plzeň</strong></span><br /><span style=\"font-size: small;\">22. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.rozhlas.cz/zpravy/regiony/_zprava/veletrh-klic-k-prilezitostem-nabidne-uz-podruhe-lidem-praci-i-vzdelavani--1306565\">http://www.rozhlas.cz/zpravy/regiony/_zprava/veletrh-klic-k-prilezitostem-nabidne-uz-podruhe-lidem-praci-i-vzdelavani--1306565</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>Plzeň 2015</strong></span><br /><span style=\"font-size: small;\">21. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.plzen2015.cz/cs/aktuality/hledate-nove-misto-zkuste-veletrh-prace-a-vzdelavani\">http://www.plzen2015.cz/cs/aktuality/hledate-nove-misto-zkuste-veletrh-prace-a-vzdelavani</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>QAP.cz</strong></span><br /><span style=\"font-size: small;\">21. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.qap.cz/zpravy/zpravy-plzen/object/hledate-praci-nebo-jen-brigadu-v-plzni-se-chysta-veletrh-prace-a-vzdelavani-55353/article.htm\">http://www.qap.cz/zpravy/zpravy-plzen/object/hledate-praci-nebo-jen-brigadu-v-plzni-se-chysta-veletrh-prace-a-vzdelavani-55353/article.htm</a></span></p>\r\n<p><span style=\"font-size: small;\"><strong>PrvníZprávy.cz</strong></span><br /><span style=\"font-size: small;\">19. 1. 2014</span><br /><span style=\"font-size: small; text-decoration: underline;\"><a href=\"http://www.prvnizpravy.cz/zpra