INSERT INTO `paper` VALUES ('2794', '2093', null, 'Nabízená pracovní místa', '<p><span style=\"font-family: verdana, geneva;\"><strong>Každ&yacute; rok je nab&iacute;dka pracovn&iacute;ch m&iacute;st jin&aacute; a vždy pestr&aacute;.<br>Seznam nab&iacute;zen&yacute;ch pracovn&iacute;ch m&iacute;st pro rok 2024:</strong></span></p>\r\n<div class=\"\" data-template=\"two_columns_divided\">\r\n<div class=\"dva-sloupce-nadpis\">\r\n<div class=\"ui two column grid stackable \">\r\n<div class=\"seven wide column\">\r\n<div>ASISTENT VEDOUC&Iacute;HO PROJEKTU (m/ž)</div>\r\n<div>CNC Soustružn&iacute;k &ndash; Fr&eacute;zař (m/ž)</div>\r\n<div>Děln&iacute;k v potravin&aacute;řsk&eacute; v&yacute;robě</div>\r\n<div>Děln&iacute;k ve v&yacute;robě</div>\r\n<div>Design engineer</div>\r\n<div>Disponent/ka ř&iacute;zen&iacute; v&yacute;roby</div>\r\n<div>Doručovatel listovn&iacute; pě&scaron;&iacute; / motorizovan&yacute;</div>\r\n<div>Ekolog</div>\r\n<div>Ekonom stavby</div>\r\n<div>Elektrik&aacute;ř</div>\r\n<div>Elektrik&aacute;ř (Janovice)</div>\r\n<div>Elektrik&aacute;ř (m/ž)</div>\r\n<div>Elektrokonstrukt&eacute;r</div>\r\n<div>Elektromechanik</div>\r\n<div>Elektrotechnik</div>\r\n<div>Finančn&iacute; controlling</div>\r\n<div>Finančn&iacute; expert</div>\r\n<div>Chemik &ndash; stř&iacute;dač CH&Uacute;V</div>\r\n<div>IT administr&aacute;tor</div>\r\n<div>IT konzultant SAP</div>\r\n<div>IT specialista</div>\r\n<div>Kalkulant</div>\r\n<div>Klientsk&yacute; pracovn&iacute;k</div>\r\n<div>Konstrukt&eacute;r</div>\r\n<div>Kontrolor UT level 2</div>\r\n<div>Kur&yacute;r bal&iacute;kov&yacute;ch z&aacute;silek</div>\r\n<div>Maintenance Technician</div>\r\n<div>Manažer prodeje</div>\r\n<div>Mechanik M+R</div>\r\n<div>Mechatronik</div>\r\n<div>Mistr</div>\r\n<div>MISTR STAVBY / POL&Iacute;R (m/ž)</div>\r\n<div>Mont&eacute;r v&nbsp;zak&aacute;zkov&eacute; v&yacute;robě (m/ž)</div>\r\n<div>N&aacute;kupč&iacute; (m/ž)</div>\r\n<div>N&aacute;kupč&iacute; /n&aacute;kupč&iacute; senior</div>\r\n<div>N&aacute;strojař a Seřizovač (Žebr&aacute;k)</div>\r\n<div>Obsluha CNC</div>\r\n<div>Obsluha CNC fr&eacute;zky</div>\r\n<div>Obsluha ohraňovac&iacute;ho lisu</div>\r\n<div>Oper&aacute;tor logistiky</div>\r\n<div>Oper&aacute;tor na klemp&iacute;rně</div>\r\n<div>Oper&aacute;tor ve v&yacute;robě</div>\r\n<div>P&aacute;ječ</div>\r\n<div>Parť&aacute;k lakovna</div>\r\n<div>Pl&aacute;novač v&yacute;roby (m/ž)</div>\r\n<div>PLC oper&aacute;tor</div>\r\n<div>PPAP Engineer</div>\r\n<div>Pracovn&iacute;k auto&uacute;držby</div>\r\n<div>Pracovn&iacute;k kontroly kvality (m/ž)</div>\r\n<div>Pracovn&iacute;k mezioperačn&iacute; a v&yacute;stupn&iacute; kontroly</div>\r\n<div>Pracovn&iacute;k s licenc&iacute; strojvedouc&iacute;ho</div>\r\n<div>Pracovn&iacute;k &uacute;držby</div>\r\n<div>Pracovn&iacute;k &uacute;držby n&aacute;strojů (m)</div>\r\n<div>Pr&aacute;&scaron;kov&yacute; lak&yacute;rn&iacute;k</div>\r\n<div>Procesn&iacute; specialista</div>\r\n<div>Process Engineer</div>\r\n<div>Product engineer</div>\r\n</div>\r\n<div class=\"seven wide column\">\r\n<div>Production Supervisor</div>\r\n<div>Produktov&yacute; manažer (m/ž)</div>\r\n<div>Program&aacute;tor p&aacute;lic&iacute;ch strojů</div>\r\n<div>Provozn&iacute;ho technika v&yacute;měn&iacute;kov&yacute;ch stanic</div>\r\n<div>Před&aacute;k v&yacute;robn&iacute;ho provozu</div>\r\n<div>Př&iacute;prav&aacute;ř</div>\r\n<div>PŘ&Iacute;PRAV&Aacute;Ř, KALKULANT (m/ž)</div>\r\n<div>Rozpočt&aacute;ř dr&aacute;žn&iacute; stavby</div>\r\n<div>Rozpočt&aacute;ř staveb</div>\r\n<div>Řidič C (možno i brig&aacute;dně)</div>\r\n<div>Řidič C + E (možno i brig&aacute;dně)</div>\r\n<div>ŘIDIČ sk. C / C+E (m/ž)</div>\r\n<div>ŘIDIČ sk. C+E (m/ž)</div>\r\n<div>Sales Manager</div>\r\n<div>Seřizovač kontroln&iacute;ch automatů</div>\r\n<div>Seřizovač/ka v&yacute;robn&iacute; linky</div>\r\n<div>Seřizovače mont&aacute;žn&iacute;ch linek (m/ž)</div>\r\n<div>Seřizovače vstřikovac&iacute;ch lisů (m/ž)</div>\r\n<div>Signalista</div>\r\n<div>Skladn&iacute;k</div>\r\n<div>Skladn&iacute;k (m/ž)</div>\r\n<div>Skladn&iacute;k / řidič VZV</div>\r\n<div>Směnov&yacute; auditor kvality</div>\r\n<div>Softwarov&yacute; v&yacute;voj&aacute;ř</div>\r\n<div>Specialista kvality &ndash; zav&aacute;děn&iacute; nov&yacute;ch d&iacute;lů</div>\r\n<div>Specialista na udržitelnost ve v&yacute;stavbě</div>\r\n<div>Specialista n&aacute;kupu</div>\r\n<div>Specialista podpory trhu.</div>\r\n<div>Specialista prodeje produktů ČEZ</div>\r\n<div>Specialista TZB</div>\r\n<div>STAVBYVEDOUC&Iacute; (m/ž)</div>\r\n<div>STAVEBN&Iacute; DĚLN&Iacute;K (m/ž)</div>\r\n<div>Stavebn&iacute; strojn&iacute;k</div>\r\n<div>Stavebn&iacute; technik</div>\r\n<div>Strojn&iacute;k</div>\r\n<div>STROJN&Iacute;K (m/ž)</div>\r\n<div>Sv&aacute;řeč-z&aacute;mečn&iacute;k</div>\r\n<div>Svozov&yacute; specialista</div>\r\n<div>Technick&yacute; specialista schvalov&aacute;n&iacute; d&iacute;lů</div>\r\n<div>Technick&yacute; trainee</div>\r\n<div>Technik do t&yacute;mu &uacute;držby</div>\r\n<div>Technik kvality</div>\r\n<div>Technik v&yacute;roby</div>\r\n<div>Technik zav&aacute;děn&iacute; nov&yacute;ch modelů</div>\r\n<div>TESAŘ (m/ž)</div>\r\n<div>Trainee</div>\r\n<div>Tř&iacute;dič/ka</div>\r\n<div>&Uacute;držb&aacute;ř</div>\r\n<div>VEDOUC&Iacute; PROJEKTU (m/ž)</div>\r\n<div>Vedouc&iacute; t&yacute;mu v&yacute;roby (m/ž)</div>\r\n<div>V&yacute;pravč&iacute;</div>\r\n<div>Zabezpečovac&iacute; technik</div>\r\n<div>Z&aacute;mečn&iacute;k</div>\r\n<div>Z&aacute;mečn&iacute;k kotelny</div>\r\n<div>Zauhlovač</div>\r\n<div>ZEDN&Iacute;K (m/ž)</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p>&nbsp;</p>', '', 'práce, místa, volná místa, zaměstnání', 'kasl2405', '2024-01-26 12:18:22');
